    body: "エリク・エリクソン（1902-1994）はドイツ生まれの発達心理学者で、人間の発達を乳児期から老年期までの8つの段階に分け、各段階で乗り越えるべき心理社会的な課題があるとする理論を提唱しました。主著『幼年期と社会』（1950年）にその理論の原型が示されています。フロイトの精神分析の影響を受けつつも、生涯にわたって発達が続くという生涯発達の視点を新たに導入した点に大きな特徴があります。\n\n特に思春期・青年期の課題として示した「アイデンティティの確立」は、「自分とは何者か」という感覚を築く時期であるとし、教育心理学や生徒指導の分野で広く参照される概念となりました。各段階には対となる心理社会的危機が設定されており、たとえば乳児期は「基本的信頼対不信」、児童期は「勤勉性対劣等感」、青年期は「同一性対役割の混乱」とされています。\n\n各段階の課題をうまく乗り越えられないと、その後の発達に影響を及ぼす可能性があるとされ、学校教育においても、児童生徒の発達段階に応じた関わり方や、思春期特有の悩みや揺れを理解するための重要な理論的枠組みとして、教員養成課程などでも幅広く教えられています。",
