    body: "ジェローム・ブルーナー（1915-2016）はハーバード大学で活躍した心理学者・教育学者で、1950～60年代にアメリカで起きた「認知革命」を牽引した中心人物の一人として知られています。教育学においては、教師が知識を一方的に与えるのではなく、学習者自身が概念や法則性を能動的に探求し発見していく過程を重視する「発見学習」の考え方を提唱しました。\n\nまた、知識の獲得過程を「行動的表象（動作を通じた理解）」「映像的表象（イメージを通じた理解）」「象徴的表象（言語や記号を通じた理解）」という3つの表象モードでとらえる独自の認知発達論を示し、どのような内容であっても、発達段階に応じた適切な形で提示すれば子どもは理解できるという知的に誠実な立場を取りました。\n\nこの考え方は、基礎的で重要な概念を学年が上がるごとに繰り返し取り上げながら、より高度で抽象的な形へと学び直させていく「らせん型カリキュラム」の発想へとつながり、日本の教育課程論やカリキュラム編成、教科教育の指導計画づくりにも大きな影響を与え続けています。",
