    body: "アブラハム・マズロー（1908-1970）は、人間の動機づけのあり方を研究し、欲求を低次のものから高次のものへと段階的に位置づける「欲求階層説」を1943年の論文で発表しました。行動主義や精神分析とは異なる立場から、人間の健全な成長や可能性そのものに注目する「人間性心理学」の創始者の一人としても広く知られています。\n\n階層は下から「生理的欲求（食事や睡眠など生命維持に関わる欲求）」「安全の欲求（身の安全や生活の安定を求める欲求）」「社会的欲求（集団への所属や愛を求める欲求）」「承認（尊重）の欲求」「自己実現の欲求（自分の可能性を最大限に発揮したいという欲求）」の5段階からなり、下位の欲求がある程度満たされることで、人はより上位の欲求を求めるようになると考えました。\n\n教育現場では、児童生徒が安心して学習に取り組むためには、まず安全や所属・承認といった基礎的な欲求が満たされている必要があるという視点として参照されており、生徒指導や学級経営のあり方、学習意欲の背景にある心理的な要因を考える際の実践的な枠組みとしても広く用いられています。",
