    summary:
      "学習が効果的に成立するために学習者の側に必要とされる、心身の準備状態のこと。知的発達の水準や既に習得している知識・技能、興味関心などから構成される、教育心理学における基本概念である。",
    body: "レディネス（readiness）とは、ある学習内容を効果的に習得するために必要となる、学習者側の心身の準備が整った状態を指す教育心理学の概念です。単に生活年齢だけでなく、知能や興味、運動能力、既有の知識・経験などが総合的に整っていることが、学習成立の条件とされます。\n\nレディネスが十分に形成されていない段階で学習を無理に進めても、内容の理解が浅くなったり、学習の効率が悪くなったりすることが知られています。逆に、心身の準備が整った適切なタイミングで学習を始めることで、児童生徒は興味を持ちながら、より効果的に知識・技能を習得しやすくなるとされています。\n\nゲゼルらの成熟優位説では、レディネスは生得的な心身の成熟によって自然に形成されると考えられましたが、後にヴィゴツキーの発達の最近接領域の議論に見られるように、教育的な働きかけによってレディネスの形成そのものを促すことができるという立場も示され、両者は現在の発達観の中で互いに補完的な視点として位置づけられています。教師が指導計画を立てる際にも、児童生徒のレディネスを見極めることが欠かせない配慮とされています。",
    relatedSlugs: ["zpd", "ninchi-hattatsu", "kobetsu-saiteki"],
