    summary:
      "知識は外部から一方的に伝達されるものではなく、学習者自身が経験や他者との相互作用を通じて能動的に構築していくものだとする学習観・認識論であり、学習者中心の授業デザインの基盤となっている。",
    body: "構成主義（コンストラクティビズム）とは、「知る」ということを、学習者が自分自身の中に意味や理解を組み立てていく能動的な過程としてとらえる学習理論・認識論です。ジャン・ピアジェの発生的認識論を出発点とし、その後、心理学や教育学のさまざまな立場へと発展的に展開してきました。\n\n従来の伝達型の教育観では、教師が持つ知識を学習者にそのまま「コピー」することが目指されましたが、構成主義の立場では、学習者は自らの既有の知識や経験を土台にしながら、新しい情報を主体的に解釈し、自分なりの意味を作り上げていく能動的な存在として位置づけられます。\n\nさらに、レフ・ヴィゴツキーの理論を踏まえ、知識の構成は個人の中だけで完結するのではなく、他者との対話や協働を通じて社会的になされるとする「社会的構成主義」の立場も広く示されています。この考え方は、協同学習やアクティブ・ラーニング、探究学習など、今日の学習者中心の授業デザインを支える重要な理論的基盤の一つとなっており、日本の授業改善の議論でもたびたび参照されています。",
    relatedSlugs: ["kyodo-gakushu", "active-learning"],
    isCanonical: true,
    tags: ["学習観", "知識構成", "社会的構成主義"],
