    body: "アルバート・バンデューラ（1925-2021）が体系化した社会的学習理論は、人間の学習が自分自身の経験に対する強化だけでなく、他者（モデル）の行動やその結果を観察することによっても成立すると考える理論です。この観察を通じた学習は「観察学習」あるいは「モデリング」と呼ばれ、直接経験できない事柄も他者を通じて効率よく学べることを示しました。\n\nバンデューラは、観察学習が「注意（モデルの行動に注目する）」「保持（見た行動を記憶として保持する）」「再生（記憶をもとに実際の行動として再現する）」「動機づけ（その行動を実行するかどうかを決める）」という4つの過程を経て成立すると説明しました。大人の攻撃的な行動を見た子どもが同様の行動を模倣する「ボボ人形実験」は特に有名な研究です。\n\nこの理論は、教師や仲間の望ましい行動を手本として示すことの教育的な意義を裏づけるものであり、生徒指導や道徳教育、体育・技能教科の指導など幅広い場面で応用されています。なお、バンデューラは後に「自己効力感」の概念も提唱し、教育心理学における動機づけ研究にも大きな影響を与えました。",
