    body: "記憶の二重貯蔵モデル（多重貯蔵モデル）は、アメリカの心理学者リチャード・アトキンソンとリチャード・シフリンが1968年に発表した、記憶の仕組みを説明する情報処理モデルです。外界からの情報は、まずごく短時間だけ保持される「感覚記憶」に入り、その中で注意を向けられた情報だけが次の「短期記憶」へと移されるとされます。\n\n短期記憶は保持できる容量にも保持時間にも限りがありますが、リハーサル（頭の中で繰り返す反復操作）などの処理を経ることで、より長期間かつ大量に保持できる「長期記憶」へと転送されると考えられています。発表当初は短期記憶と長期記憶からなる二重構造として提案されたため「二重貯蔵モデル」と呼ばれ、後に感覚記憶が加えられて「多重貯蔵モデル」とも呼ばれるようになりました。\n\nこのモデルは、後に提唱された「ワーキングメモリ」概念の理論的な基礎となり、授業で情報を小分けにして提示することの重要性や、繰り返し学習の効果を裏づける理論的枠組みとして、教育心理学や認知心理学の分野で広く参照され続けています。",
    relatedSlugs: ["working-memory", "forgetting-curve", "cognitive-load-theory"],
    isCanonical: true,
    tags: ["短期記憶", "長期記憶", "情報処理モデル"],
