      "ハンガリー出身の心理学者チクセントミハイが提唱した概念。ある活動に完全に没頭し、時間の感覚を忘れるほど深く集中している最適な心理状態「フロー」が生じる条件を説明する心理学理論である。",
    body: "ミハイ・チクセントミハイ（1934-2021）は、人が特定の活動に深く没頭し、高い集中力と充実感を伴いながら取り組んでいる状態を「フロー（flow）」と名づけ、その心理的な条件を実証的に研究しました。主著『フロー体験 喜びの現象学』（原著1990年）によって、その考え方は世界的に広く知られるようになりました。\n\nフロー状態は、取り組む課題の難易度と本人が持つスキルの水準とが釣り合っているときに生じやすいとされます。課題があまりに易しすぎれば退屈な状態になり、逆に難しすぎれば不安が強くなり、いずれの場合もフローには至りにくいとされます。この釣り合いに加え、目標が明確であることや、行動の結果に対して即座のフィードバックが得られることも重要な条件として挙げられています。\n\nチクセントミハイは、人間の幸福感や生きがいを科学的に研究する「ポジティブ心理学」の発展にも大きく寄与しました。教育においては、児童生徒の力量に応じて適度に挑戦的な課題を設定することが、学習への内発的な没頭や意欲の高まりにつながるという実践的な示唆を与える理論として、授業づくりの中で参照されています。",
    relatedSlugs: ["naihatsu-doki", "kobetsu-saiteki"],
    isCanonical: true,
    tags: ["チクセントミハイ", "没頭", "ポジティブ心理学"],
