    title: "達成目標理論",
    reading: "たっせいもくひょうりろん",
    kana: "た",
    categories: ["psychology"],
    summary:
      "1980年代にドゥエックやニコルズらが提唱した動機づけ理論。学習者が課題に取り組む際にどのような目標を抱くかによって、学習行動や感情、粘り強さのあり方が大きく異なると説明する理論である。",
    body: "達成目標理論は、1980年代にアメリカの心理学者キャロル・ドゥエックやジョン・ニコルズらによって展開された、学習における動機づけを説明する理論です。学習者が課題に取り組む際に抱く目標の質そのものに注目し、その違いが学習方略や課題への粘り強さに大きく影響すると考えます。\n\n代表的な分類として、能力の向上や理解を深めること自体を重視する「熟達目標（学習目標）」と、他者との比較において優れているという評価を得ることを重視する「遂行目標（成績目標）」があります。熟達目標を持つ学習者は、失敗を成長の機会としてとらえ、困難な課題にも粘り強く取り組みやすいことが、多くの研究によって示されています。\n\n遂行目標はさらに、良い評価を得ようとする「遂行接近目標」と、悪い評価を避けようとする「遂行回避目標」に分けられ、特に遂行回避目標は学習への不安を高め、深い理解の妨げになりやすいことが指摘されています。この理論は、教師の評価の仕方やフィードバックの与え方、声かけのあり方を考えるうえで重要な視点を提供しています。",
