    summary:
      "イギリスの精神科医・心理学者。乳幼児が特定の養育者との間に築く情緒的な絆「愛着（アタッチメント）」の概念を体系化し、愛着理論を確立した、発達心理学において極めて重要な位置を占める人物である。",
    body: "ジョン・ボウルビィ（1907-1990）は、第二次世界大戦後の戦争孤児や施設で育った子どもたちに関する調査などを通じて、乳幼児期に特定の養育者から十分な世話を受けられないことが、その後の情緒や対人関係の発達に深刻な影響を及ぼしうることを明らかにし、「愛着理論」を確立しました。世界保健機関（WHO）の依頼による調査報告もその研究の一つとして知られています。\n\n愛着（アタッチメント）とは、乳幼児が不安や恐れを感じたときに、特定の養育者に近づいたり、その存在を求めたりすることによって安心感を得ようとする情緒的な絆のことです。ボウルビィは、この愛着関係が生後の限られた期間を通じて段階的に形成されていくプロセスを詳しく説明しました。\n\nまた、養育者との関係の中で子どもの中に築かれていく「内的作業モデル」は、その後の対人関係や社会性のあり方の基礎になると考えられており、この理論は保育・幼児教育や学校での児童生徒理解、特別支援教育など、子どもの心理的な安定を支える実践の理論的基盤として今も広く参照されており、保育士や教員の養成課程でも重視されている考え方です。",
