      "ロシアの生理学者パブロフが「パブロフの犬」の実験で発見した学習の原理。本来は無関係な刺激が、生得的な反応を引き起こす刺激と結びつくことで、単独でも同じ反応を引き起こすようになる現象を指す。",
    body: "古典的条件づけ（レスポンデント条件づけ）は、ロシアの生理学者イワン・パブロフ（1849-1936）が、消化腺の働きに関する研究の過程で偶然発見した学習の仕組みです。犬にベルの音を聞かせながら餌を与えることを繰り返すと、やがてベルの音を聞かせただけで唾液が分泌されるようになるという実験によって世界的に広く知られています。\n\nこの現象では、もともと唾液分泌などの生得的な反応（無条件反応）を引き起こす刺激（無条件刺激、この場合は餌）に対し、本来は無関係な刺激（中性刺激、この場合はベルの音）を繰り返し対にして提示することで、中性刺激が「条件刺激」となり、単独でも同じような反応（条件反応）を引き起こすようになります。\n\nこの原理は、スキナーのオペラント条件づけと並ぶ行動主義心理学の基礎理論であり、恐怖や不安、好き嫌いといった情緒的な反応が経験を通じて学習されていく仕組みを説明するものとして、教育心理学や学校での情緒面の指導、児童生徒の行動上の問題への理解にも活用されており、生徒指導の実践にも生かされています。",
    relatedSlugs: ["operant-conditioning"],
    isCanonical: true,
    tags: ["パブロフ", "レスポンデント条件づけ", "行動主義"],
