    body: "認知負荷理論は、オーストラリアの教育心理学者ジョン・スウェラーが1980年代後半に提唱した理論で、学習中に学習者のワーキングメモリにかかる負荷（認知負荷）に注目します。ワーキングメモリの容量には明確な限りがあるため、負荷が過剰になると、新しい情報を長期記憶に定着させるための処理がうまく進まなくなると考えます。\n\n認知負荷は、学習内容そのものの本質的な複雑さに由来する「課題内在性負荷」、教材の提示方法など学習に不必要な要因による「課題外在性負荷」、そして知識をひとまとまりの体系（スキーマ）として構築するために必要な「学習関連負荷」の3種類に分類されます。効果的な教材設計では、外在性負荷をできるだけ減らし、学習関連負荷に認知資源を振り向けることが重要だとされます。\n\nこの理論は、図と文章を近接して配置する、学習に無関係な装飾情報を減らす、支援を段階的に減らしていくなど、具体的なインストラクショナルデザインの原則として、教材開発や授業設計、ICTを活用した学習コンテンツづくりに広く応用され続けています。",
