    body: "ハワード・ガードナー（1943-）は、著書『Frames of Mind』（1983年）の中で、知能を単一の指標（IQ）で測れるものとしてとらえるのではなく、互いに独立した複数の能力の集合体としてとらえる「多重知能理論（MI理論）」を提唱しました。人によって強い知能と弱い知能の組み合わせはそれぞれ異なるという立場に立っています。\n\nガードナーが当初示した知能は、言語的知能、論理数学的知能、音楽的知能、身体運動感覚的知能、空間的知能、対人的知能、内省的知能、博物学的知能の8種類です。後年、実存的知能を追加候補として挙げるなど、理論そのものも研究の進展にあわせて継続的に見直されてきました。\n\nこの理論は、学力テストで測られる能力だけが「知能」ではないという視点を教育界に提供し、学習者一人ひとりの得意な学び方や表現方法を尊重する個別最適な指導や、多様な評価方法を模索する教育実践に大きな影響を与えました。一方で、各知能の存在を実証的に検証することの難しさを指摘する学術的な批判も根強く存在しています。",
