    body: "ヘルマン・エビングハウス（1850-1909）は、1880年代に「意味のないつづり」と呼ばれる、無意味な文字の羅列を記憶材料として用いた実験を、自ら被験者となって繰り返し行いました。感覚や知覚の研究が中心だった当時の心理学において、高次な精神機能である記憶を実験的に研究する道を切り開いた先駆的な業績として高く評価されています。\n\n実験の結果、いったん記憶した内容は学習の直後から急速に忘れられ、その後は忘却の進み方が次第に緩やかになっていくという傾向が見出され、これをグラフに表したものが「忘却曲線」です。学習からわずか20分後には内容の半分近くを、1日後にはその多くを忘れてしまうことが示されました。\n\nこの結果は、一度学習した内容も時間の経過とともに急速に失われやすいこと、そして忘れかけた頃合いで復習を行うこと（分散学習・反復学習）が記憶の定着に効果的であることを示唆するものとして、学習方法の指導や指導計画、宿題・小テストの設計などに広く応用され続けており、家庭学習の指導でもしばしば紹介されます。",
