    body: "自己調整学習（Self-Regulated Learning）は、1980年代後半にアメリカの教育心理学者バリー・ジマーマンらによって体系化された理論的枠組みです。教師から与えられる知識を受け身のまま受け取るだけの学習者像ではなく、自らの学習過程そのものに能動的に関わっていく学習者像を提示した点に大きな特徴があります。\n\n自己調整学習は一般に、学習に取り組む前に目標を設定し計画を立てる「予見の段階」、実際に学習方略を用いながら学習を進めていく「遂行制御の段階」、学習を終えたあとに結果を振り返り自己評価を行う「自己内省の段階」という循環的な過程としてとらえられます。この過程を繰り返すことを通じて、学習方略が次第に洗練されていくと考えられています。\n\nこの理論は、メタ認知や動機づけに関する研究とも密接に関わっており、日本の学習指導要領が重視する「主体的・対話的で深い学び」のうち「主体的な学び」を支える理論的な裏づけの一つとしても位置づけられ、家庭学習の指導や学習方略の指導などに広く活用されています。",
