      "アメリカの心理学者デシとライアンが提唱した動機づけ理論。「自律性」「有能感」「関係性」という3つの基本的心理欲求が満たされることで、内発的動機づけが自然に高まっていくとする理論である。",
    body: "自己決定理論（Self-Determination Theory）は、エドワード・デシとリチャード・ライアンによって長年にわたり展開されてきた動機づけの理論で、人間には生まれつき「自律性への欲求」「有能感への欲求」「関係性への欲求」という3つの基本的心理欲求が備わっていると考えます。\n\n「自律性」は自分自身の意志や価値観に基づいて行動できているという感覚、「有能感」は課題にうまく取り組めているという感覚、「関係性」は他者とのつながりや信頼を感じられているという感覚を指します。これらの欲求が満たされる環境のもとでは、報酬などの外的な要因に頼らずとも内発的動機づけが自然に高まりやすいとされます。\n\nまた、外発的動機づけについても、外部から与えられた価値観を自分自身の中にどれだけ取り込めているかによって自律性の度合いが異なるとする段階的なとらえ方（外発的動機づけの内在化）を示している点も特徴です。この理論は、児童生徒の主体的な学びを支える学級環境や、教師の日々の関わり方を考えるうえで重要な視点として教育現場でも広く参照されています。",
