    summary:
      "満足な結果を伴う反応は結合が強化され、不快な結果を伴う反応は弱まるとするソーンダイクの学習法則です。",
    body: "効果の法則は、アメリカの心理学者エドワード・ソーンダイクが猫の問題箱実験をもとに提唱した学習理論です。ある状況における反応がその後に満足な結果をもたらすと、その状況と反応の結合が強まり、不快な結果をもたらすと結合が弱まるという原理を指します。連合説（結合説）と呼ばれる学習理論の中核的な法則の一つです。\n\nソーンダイクは箱から脱出しようとする猫の試行錯誤の様子を観察し、成功に結びついた行動が繰り返されるようになる過程を「試行錯誤学習」として説明しました。効果の法則はのちにスキナーのオペラント条件づけにおける強化の概念へと発展し、行動主義心理学の基盤の一つとなりました。\n\n教育現場では、望ましい行動や正答に対して即座に肯定的なフィードバックや賞賛を与えることが学習の定着を促すという考え方の理論的根拠となっています。ドリル学習や行動修正の技法にも応用され、褒めることの教育的意義を裏づける古典的理論として今も参照されています。",
