    body: "9教授事象は、アメリカの教育心理学者ロバート・ガニェが提唱した授業設計の枠組みです。人が新しい知識やスキルを習得する際の情報処理過程を分析し、学習者の内的な認知プロセスを支援するために教師が行うべき働きかけを、注意の喚起から学習目標の提示、既習事項の想起、フィードバックの提供などを含む9つの段階に整理したものです。\n\nこの9つの事象は「導入・情報提示・学習活動・まとめ」という大きな4段階に分けて理解することができ、それぞれの段階で学習者の記憶過程に働きかける具体的な指導行動が対応づけられています。ガニェの学習成果の5分類（言語情報・知的技能・認知的方略・態度・運動技能）と組み合わせて用いられることが多い理論です。\n\nインストラクショナルデザインの基本モデルとして、学校教育のみならず企業研修やeラーニング教材の設計にも広く応用されています。授業の展開を構造的に点検し、学習効果を高めるためのチェックリストとして活用できる点に教育現場での意義があります。",
