    body: "ARCSモデルは、アメリカの教育心理学者ジョン・ケラーが1983年に提唱した学習意欲向上のためのモデルです。学習者の動機づけを高めるために指導者が配慮すべき要素を、注意（Attention）・関連性（Relevance）・自信（Confidence）・満足感（Satisfaction）の頭文字をとって整理しています。\n\n注意は新奇性や疑問による興味の喚起、関連性は学習内容と学習者の目標や興味との結びつけ、自信は成功体験を通じた「やればできる」という感覚の醸成、満足感は努力の成果を実感させることを指します。これら4要素は授業や教材の各場面で相互に関連し合いながら学習者の動機づけを支えます。\n\n教材開発や授業設計の際に、この4観点をチェックリストとして用いることで、学習者が意欲を持って取り組める指導計画を具体的に検討できます。eラーニングや教育工学の分野でも動機づけ設計の代表的な枠組みとして広く活用されています。",
