    body: "期待価値理論は、ある課題に取り組む動機づけの強さが、その課題を成功させられるという「期待」と、その課題を行うことの「価値」の掛け合わせによって決まるとする心理学理論です。アトキンソンの達成動機理論を起点とし、その後エクルズらによって学業場面における動機づけモデルとして発展しました。\n\n期待は自己効力感や過去の成功経験に基づく見込みであり、価値には興味関心による内発的価値、将来の目標に対する利用価値、課題の重要性を示す達成価値、そして負担感を示すコストが含まれます。期待も価値も低いと学習者は課題を回避しやすくなり、両方が高いほど積極的に取り組むとされます。\n\n学習者がなぜ特定の教科や活動に意欲を示さないのかを分析する枠組みとして、進路指導やキャリア教育の場面でも活用されています。教師が学習内容の意義を伝え、達成可能感を持たせる指導の重要性を裏づける理論です。",
