    body: "原因帰属理論は、アメリカの心理学者バーナード・ワイナーが提唱した動機づけ理論です。人は自分の成功や失敗の原因を能力・努力・課題の難易度・運などの要因に帰属させ、その帰属の仕方によってその後の感情や意欲が変化すると考えます。\n\nワイナーは原因の性質を「統制の所在（内的か外的か）」「安定性（時間的に安定か不安定か）」「統制可能性（自分でコントロールできるか）」という3つの次元で整理しました。例えば失敗を「努力不足」という内的で統制可能な原因に帰属すると恥や罪悪感とともに次への意欲が高まりやすく、「運が悪かった」という外的で不安定な原因に帰属すると意欲は高まりにくいとされます。\n\n教育現場では、教師の言葉かけが児童生徒の原因帰属のあり方に影響を与えることから、失敗の原因を努力や方略といった統制可能な要因に帰属させるような指導が、学習性無力感を防ぎ意欲を持続させる上で重要だとされています。",
