    body: "グロースマインドセット（成長マインドセット）は、アメリカの心理学者キャロル・ドゥエックが提唱した、知能や能力は努力や経験によって伸ばすことができると信じる考え方です。これに対し、能力は生まれつき固定されていて変わらないと考える立場は「フィックストマインドセット」と呼ばれます。\n\nドゥエックの研究では、成長マインドセットを持つ学習者は困難な課題や失敗を成長の機会と捉え挑戦を続けやすいのに対し、固定マインドセットを持つ学習者は失敗を能力の限界と結びつけて挑戦を避けやすい傾向が示されています。褒め方の違い（結果や能力を褒めるか、努力や過程を褒めるか）がマインドセットの形成に影響することも報告されています。\n\n学校教育では、結果だけでなく努力や工夫の過程を評価するフィードバックを行うことで、児童生徒に成長マインドセットを育み、失敗を恐れずに挑戦する姿勢やレジリエンスを育てる指導が重視されています。",
