    body: "シェマ理論は、イギリスの心理学者フレデリック・バートレットが物語の再生実験を通じて提唱した記憶理論です。人は経験や知識から形成された既存の枠組みである「シェマ（図式）」を用いて新しい情報を解釈し、記憶の際にはその内容をシェマに合わせて省略・変形・再構成すると考えます。\n\nバートレットは、異文化の民話を被験者に読ませて時間をおいて再生させる実験を行い、再生された内容が原文をそのまま復元するのではなく、被験者自身の文化的な知識や既有のシェマに合わせて変化することを示しました。この結果は、記憶が受動的な記録ではなく能動的な再構成の過程であることを示す先駆的な知見とされています。\n\nこの理論は後の認知心理学における知識構造の研究やスキーマ理論に大きな影響を与え、教育現場では、学習者が持つ既有知識（前提知識）が新しい学習内容の理解や記憶のされ方に影響することを踏まえた授業設計の重要性を示す根拠となっています。",
