    body: "二重過程理論とは、人間の思考や判断が性質の異なる2つの認知過程によって行われるとする理論です。心理学者スタノビッチやカーネマンらの研究で広く知られ、直感的・自動的で速く処理される「システム1」と、意識的・論理的で努力を要し処理が遅い「システム2」という2種類の思考モードが想定されています。\n\n日常の多くの判断はシステム1によって素早く処理されますが、複雑な問題解決や新奇な課題では、システム1の直感的判断を吟味し修正するためにシステム2が働くとされます。システム1に頼りすぎると認知バイアスによる誤った判断が生じやすく、システム2による熟慮がこれを補正する役割を果たします。\n\n教育においては、直感的な誤概念や思い込みをシステム2の批判的思考によって検討させる指導が、科学的概念の理解や論理的な問題解決能力の育成に重要だと考えられています。批判的思考力の育成やメタ認知指導の理論的背景としても参照されます。",
