      "自分が属する集団への否定的な固定観念を意識することで実際にパフォーマンスが低下する現象です。",
    body: "ステレオタイプ脅威とは、自分が属する社会集団に対する否定的なステレオタイプ（固定観念）を意識することで、不安や過度な自己監視が生じ、実際に課題の成績が低下してしまう心理現象です。アメリカの心理学者クロード・スティールとジョシュア・アロンソンらの研究によって示されました。\n\n代表的な研究では、能力に関するステレオタイプが存在する集団に属する人が、そのステレオタイプを意識させられる状況でテストを受けると、意識させられない場合に比べて成績が低下することが報告されています。これは能力そのものの差ではなく、ステレオタイプを裏づけてしまうことへの不安が認知資源を消費するために生じると説明されています。\n\n教育現場では、性別や出身、学力層などに関する固定観念を教室内で強調しない配慮、テストの前にステレオタイプを想起させない工夫、生徒の帰属意識や自己効力感を高める働きかけが、ステレオタイプ脅威の影響を軽減する方策として重視されています。",
