      "単に読み返すよりも、学習内容を記憶から思い出す(検索する)練習を行う方が長期的な記憶保持を高めるという現象。ローディガーとカーピックの実験で広く知られるようになった。",
    body: "テスト効果(検索練習効果)とは、学習した内容をテストなどを通じて記憶から能動的に検索(思い出す)することが、単に教材を繰り返し読み返す(再読)よりも、長期的な記憶の保持を促進するという現象である。2006年、ヘンリー・ローディガーとジェフリー・カーピックは、大学生に科学的な文章を学習させ、一方のグループには繰り返し読ませ、他方のグループには読んだ後に内容を思い出して書き出させる実験を行った。その結果、5分後のテストでは再読群の方が成績が良かったが、1週間後のテストでは検索練習群の方が有意に高い成績を示した。この逆転現象が「テスト効果」として広く知られるようになった。\n\nこの効果のメカニズムについては、記憶を検索する行為そのものが記憶痕跡を強化し、想起しやすい形に情報を再構造化すると考えられている。単なる評価のためのテストではなく、学習の手段としてテスト(小テスト、フラッシュカード、自己説明など)を積極的に活用することの重要性を示す点で、この知見は学習科学において「高い効用を持つ学習方略」の一つとして、前述の分散学習と並んで位置づけられている。\n\n教育実践においては、単元の最後にまとめてテストを行うのではなく、授業中や家庭学習の中に低リスクの小テストやクイズ、フラッシュカードなどを頻繁に組み込む「形成的な検索練習」が推奨される。教師にとっては、テストを「評価のための道具」としてだけでなく「学習を促進するための道具」として捉え直すことが、テスト効果を活かした指導設計の鍵となる。",
