    reading: "すとれんじしちゅえーしょんほう",
    kana: "す",
    categories: ["psychology"],
    summary:
      "発達心理学者メアリー・エインズワースが考案した、乳幼児の愛着(アタッチメント)の質を実験的に測定する観察法。安定型・回避型・葛藤型・無秩序型の4つの愛着タイプを識別する。",
    body: "ストレンジ・シチュエーション法は、心理学者メアリー・エインズワースが1970年代に、ジョン・ボウルビィの愛着理論を実証的に検証するために考案した実験観察法である。見知らぬ実験室において、養育者との分離と再会、見知らぬ人物との接触といった一連の場面を乳幼児(生後12〜18か月頃)に経験させ、その際の探索行動、分離時の反応、再会時の行動を観察することで、養育者との愛着の質を分類する。この手法により、エインズワースは当初、安定型(Bタイプ)、回避型(Aタイプ)、葛藤型・抵抗型(Cタイプ)の3つの愛着パターンを識別した。\n\n安定型の子どもは、養育者を安全基地として積極的に探索行動を行い、分離時には多少の不安を示すものの、再会時には容易に落ち着きを取り戻す。回避型の子どもは、養育者の分離や再会にほとんど感情を示さず、養育者を避けるような行動をとる。葛藤型の子どもは、分離に強い苦痛を示す一方、再会時には養育者にしがみつきながらも怒りや抵抗を示し、容易に落ち着かない。その後1980年代には、メインとソロモンにより、一貫性を欠いた矛盾した行動を示す「無秩序型(Dタイプ)」が追加され、虐待や養育者の精神的問題などリスクの高い環境との関連が指摘されている。\n\nこの分類は、その後の子どもの社会性・情動発達、対人関係、学校適応などを予測する重要な指標として、発達心理学・保育学・教育相談の分野で広く用いられている。教育現場においては、乳幼児期の安定した愛着形成が、その後の自己肯定感や仲間関係の基盤となることから、保育者や教師が子どもにとっての「安全基地」としての役割を果たすことの重要性が示唆されている。",
    relatedSlugs: ["bowlby", "ryoshin-hattatsu", "resilience"],
    isCanonical: true,
