    title: "ヤーキーズ・ドットソンの法則",
    reading: "やーきーずどっとそんのほうそく",
    kana: "や",
    categories: ["psychology"],
    summary:
      "1908年にヤーキーズとドットソンが動物実験から見出した、覚醒水準(緊張・ストレス)と課題遂行の関係を示す法則。適度な覚醒で最も高い遂行を示し、課題が難しいほど最適な覚醒水準は低くなる。",
    body: "ヤーキーズ・ドットソンの法則は、心理学者ロバート・ヤーキーズとジョン・ドットソンが1908年に発表した論文に基づく、覚醒(緊張・ストレス・興奮)水準と課題遂行の関係についての経験則である。彼らはマウスに電気刺激を用いて課題を学習させる実験を行い、刺激の強さ(覚醒水準)と学習の速さとの関係を検討した。その結果、覚醒水準が低すぎても高すぎても遂行成績は低下し、適度な覚醒水準のときに最も良い成績が得られる、逆U字型(ベル型)の関係が見出された。さらに、課題が複雑で難しいほど、最適な覚醒水準はより低くなることも示された。\n\nこの法則は、後に人間の学習・作業パフォーマンスの文脈にも広く援用されるようになり、適度な緊張感(たとえば試験前のほどよい不安)はむしろ集中力やパフォーマンスを高める一方、過度な不安やストレスは思考力や記憶の想起を妨げ、パフォーマンスを低下させることの説明に用いられる。ただし、近年の研究では、この法則の実証的根拠は当初考えられていたほど強固ではなく、単純な「法則」というよりも経験的な傾向として捉えるべきだとする批判的な再検討も行われている。\n\n教育現場では、この考え方は試験不安や発表前の緊張の指導に応用される。過度なプレッシャーを与える指導は、特に複雑な思考を要する課題においてかえって成績を低下させる可能性があるため、生徒の緊張感を適切な水準に保ちながら、達成可能な目標設定や段階的な課題設計を行うことが望ましいとされる。難易度の高い課題ほど、リラックスした環境での取り組みが効果的であるという示唆は、テスト設計や授業運営における配慮点として参照される。",
