      "自分の感情の強さや表出の仕方をモニターし、状況に応じて調整する心理的プロセス。乳幼児期には養育者との「共同調整」を通じて発達し、その後徐々に自己調整へと移行する。",
    body: "感情調整(情動調整)とは、自分自身の感情の生起・強さ・持続時間・表出の仕方を、目標達成や社会的状況への適応のためにモニターし、必要に応じて変化させる心理的プロセスを指す。心理学者ジェームズ・グロスの理論的整理によれば、感情調整の方略には、感情を引き起こす状況そのものを選択・修正する「状況選択・修正」、注意の向け方を変える「注意の方向づけ(気そらしなど)」、状況の意味づけを変える「認知的再評価」、そして感情の表出行動を調整する「反応調整」などがあり、なかでも認知的再評価は長期的に見て適応的な調整方略とされることが多い。\n\n発達的には、乳幼児期の感情調整は、泣いている子どもを養育者があやす、なだめるといった「共同調整(co-regulation)」に大きく依存しており、応答的で安定した養育者との関わりが、子どものその後の自己調整能力の基盤を形成すると考えられている。就学前期には、気をそらす、なだめる、状況を再解釈するといった方略を子ども自身が徐々に用いられるようになり、児童期以降は、数を数える、深呼吸をするなど、より意図的で言語化された調整方略を習得していく。\n\n感情調整の困難は、攻撃行動や不安、抑うつ、対人関係のトラブルなど、さまざまな適応上の問題と関連することが示されており、学級経営や特別支援教育においても重要な支援対象となっている。教育現場では、感情を表す語彙の指導、落ち着くための具体的な行動(クールダウンコーナーの活用など)の教示、教師自身が落ち着いたモデルを示すことなどが、子どもの感情調整能力を育む実践として重視されている。",
