    categories: ["psychology", "methods"],
    summary:
      "コリンズ、ブラウン、ニューマンらが提唱した指導モデルで、伝統的な徒弟制の考え方を読み書きや数学などの認知的な領域に応用し、熟達者の思考過程を可視化しながら段階的に指導する方法。",
    body: "認知的徒弟制は、教育心理学者アラン・コリンズ、ジョン・シーリー・ブラウン、スーザン・ニューマンらが1980年代後半に提唱した指導モデルである。伝統的な徒弟制(職人が弟子に技術を教える方式)が、身体的な技能を見える形で示しながら指導できるのに対し、読み書きや数学の問題解決といった認知的な活動は、熟達者の思考過程が外からは見えにくいという課題がある。認知的徒弟制は、この「見えない」専門家の思考プロセスを意図的に可視化し、徒弟制的な指導法を認知的な領域に応用しようとする試みである。\n\nこのモデルは、モデリング(熟達者が課題を遂行して見せ、学習者がその思考過程を観察する)、コーチング(学習者が課題に取り組む様子を観察し、ヒントやフィードバックを与える)、スキャフォールディング(学習者が一人でできない部分を支援し、習熟に応じて支援を徐々に減らしていく)を中核的な指導方法とし、さらに、学習者自身に思考過程を言語化させる「アーティキュレーション」、自らの遂行を専門家と比較して振り返らせる「リフレクション」、学習者が自律的に問題を発見し取り組む「エクスプロレーション」を加えた6つの指導方法から構成される。\n\nこのモデルは、数学の問題解決指導(シェーンフェルドの実践)や読解指導(パリンサーとブラウンの相互教授法)など、さまざまな教科領域の指導実践に応用されてきた。教育現場への示唆としては、教師が自らの熟達した思考過程(問題の読み解き方、判断の根拠など)を意識的に言語化して示し、生徒の習熟度に応じて支援の量を調整しながら、最終的には生徒が自律的に課題に取り組めるよう指導を段階的に移行させていくことの重要性が挙げられる。",
