    body: "「マジカルナンバー7、プラスマイナス2」は、心理学者ジョージ・ミラーが1956年に発表した論文「The Magical Number Seven, Plus or Minus Two」で示した、人間の短期記憶(即時記憶)の容量に関する古典的な知見である。ミラーは、人が一度に保持できる情報の単位数は、情報の種類(数字、単語、文字など)によらず、おおむね5〜9個(平均7個)程度に収まるという多くの実験結果を整理した。重要なのは、この容量の限界が「ビット数」ではなく「チャンク(意味のまとまり)」の数で測られるという点であり、たとえば1桁の数字を7個覚えるのと、意味のある7つの単語を覚えるのとでは、後者の方がはるかに多くの情報量を含んでいるにもかかわらず、記憶できる単位の数はほぼ同じだという発見であった。\n\nこの知見から導かれるのが「チャンキング」という記憶方略である。個々のばらばらな情報を、既有知識に基づいて意味のあるより大きな単位(チャンク)にまとめることで、実質的に短期記憶に保持できる情報量を増やすことができる。たとえば、電話番号の羅列を市外局番・局番・番号のまとまりで覚えたり、歴史上の出来事を年号の語呂合わせでまとめて覚えたりすることは、チャンキングの典型例である。なお、その後の研究(ネルソン・コーワンによる2001年の研究など)では、リハーサルや長期記憶の支援を統制した場合、実際の容量の限界はおよそ4チャンク程度であるとする再検討も行われている。\n\n教育現場への示唆としては、大量の情報をばらばらに提示するのではなく、意味のあるまとまりや構造(カテゴリー分け、比喩、物語など)を用いて教材を組織化することで、生徒のワーキングメモリへの負荷を軽減し、学習内容の理解と記憶を促進できる。この考え方は、後の認知負荷理論における「内発的負荷」の管理や、板書・スライド設計における情報の構造化の重要性とも密接に関連している。",
