    slug: "identity-status-theory",
    title: "アイデンティティ・ステイタス理論",
    reading: "あいでんてぃてぃすていたすりろん",
    kana: "あ",
    categories: ["psychology"],
    summary:
      "心理学者マーシアが1960年代に提唱した、エリクソンのアイデンティティ概念を発展させた理論。「危機(探索)」と「関与(コミットメント)」の2軸から、青年期の自我同一性の状態を4類型に分類する。",
    body: "アイデンティティ・ステイタス理論は、心理学者ジェームズ・マーシアが1960年代に、エリク・エリクソンの心理社会的発達理論における「同一性対同一性拡散」という青年期の発達課題の概念を、実証的に測定可能な形に発展させた理論である。マーシアは、青年が自らの生き方・職業・価値観・イデオロギーなどについて主体的に考え選択肢を検討する「危機(探索)」と、その結果として特定の選択に対して自ら関与し取り組む「関与(コミットメント)」という2つの軸を設定し、その組み合わせによって青年期のアイデンティティの状態を4つの類型(ステイタス)に分類した。\n\n第一に「アイデンティティ達成」は、十分な探索を経て、確固たる関与(コミットメント)を確立した状態である。第二に「早期完了(フォークロージャー)」は、十分な探索を経ないまま、親などから与えられた価値観や進路にそのまま関与している状態を指す。第三に「モラトリアム」は、活発に探索を行っている最中であるものの、まだ明確な関与には至っていない、いわば危機のただ中にある状態である。第四に「アイデンティティ拡散」は、探索も関与もほとんど行われていない状態であり、進路や価値観についての方向性が定まっていない。マーシアは、青年期を通じて多くの若者が拡散や早期完了から、モラトリアムを経て達成へと移行していくことを想定した。\n\nこの理論は、青年期の進路選択やキャリア発達、価値観の形成過程を理解する枠組みとして、教育相談やキャリア教育の分野で広く活用されている。教育現場への示唆としては、青年に安易に一つの進路を早期に押し付けるのではなく、十分に選択肢を探索し葛藤する「モラトリアム」の時期を尊重しながら、最終的に主体的なコミットメントへと至る過程を支援することの重要性が挙げられる。",
