    body: "ビッグファイブは、人間のパーソナリティを5つの広い特性次元で捉える理論で、五因子モデル（FFM）とも呼ばれます。5つの次元は、神経症傾向（情緒の不安定さ）、外向性、開放性（経験への開放性）、協調性（調和性）、誠実性（勤勉性）です。人の性格を表す日常語を集めて因子分析すると似た因子構造が繰り返し見いだされる、という語彙仮説にもとづく研究から生まれ、ゴールドバーグらが「ビッグファイブ」の呼称で整理しました。\n\nその後、コスタとマクレーがNEO-PI-R（1992年のマニュアル）などの質問紙を整え、モデルを大きく普及させました。個人を「タイプ」に分類するのではなく、各次元の高低という連続的な程度で記述する点が特性論の特徴です。質問紙の日本語版も作られており、研究や進路・適性の指導で参照されます。\n\n教育心理学では、5つの次元のうち特に誠実性が学業成績と比較的一貫して関連することが報告されています。ただし、性格特性は固定的な能力判定の道具ではなく、環境や経験によって穏やかに変化しうるものです。児童生徒をラベル付けして決めつけるのではなく、個々の強みに応じた学習環境や支援を考える手がかりとして用いることが望まれます。",
