    categories: ["psychology"],
    summary:
      "ハリー・ハーロウが子ザルに針金製と布製の代理母を与えて行った実験。愛着は授乳ではなく、ふれあいによる安心感から生まれることを示した。",
    body: "アメリカの心理学者ハリー・ハーロウ（1905〜1981）は、アカゲザルの子を生後まもなく母親から離し、ミルクの出る針金製の代理母と、ミルクは出ないが柔らかい布で覆われた代理母のどちらにも近づけるようにして育てました。1950年代後半に報告された結果では、子ザルは空腹のときだけ針金の母に寄り、大半の時間を布の母にしがみついて過ごしました。恐ろしい物を見せられたときも、布の母のもとへ逃げ込みました。\n\nこの結果は、「子どもが母親を慕うのは食べ物をくれるからだ」とする二次的動因説（餌づけ説）への有力な反証となりました。ハーロウは、肌のふれあいがもたらす安心感（接触の慰め）が愛着の形成に重要だと主張しました。また、布の母が「安全基地」となって子ザルの探索行動を支える様子も観察され、のちのボウルビィの愛着理論やエインズワースの研究と響き合う知見として位置づけられています。\n\n一方で、隔離して育てられた子ザルには、のちに社会的・情緒的な深刻な困難が生じました。この事実は、乳幼児期の養育経験の重要性を示すと同時に、動物実験の倫理をめぐる議論も呼びました。保育や教育の場では、栄養や世話だけでなく、抱かれる・触れられるといった情緒的な応答が子どもの安心を支える点を示す古典的研究として参照されます。",
    relatedSlugs: ["bowlby", "ainsworth-strange-situation", "erikson", "trauma-informed-care"],
