    body: "ロバート・J・ハヴィガースト（1900〜1991）は、アメリカの教育学者・発達心理学者です。『Developmental Tasks and Education』（1948年）で、発達課題を「人生のある時期に生じる課題であり、それをうまく達成すれば幸福と後の課題の成功につながり、失敗すれば不幸や社会的な非難、後の課題での困難を招くもの」と定義しました。日本語版は荘司雅子監訳『人間の発達課題と教育』として刊行されています。\n\nハヴィガーストは人生を乳幼児期、児童期、青年期、壮年期、中年期、老年期の6段階に分けました。課題の源泉として、身体的成熟、社会からの要請、個人の価値観や願望の3つを挙げています。たとえば青年期には、同年代との新しい関係の形成、性役割の受容、親からの情緒的自立、職業選択の準備などが課題として示されました。\n\n教育との関係で重要なのが「教育可能期（teachable moment）」の考え方です。身体が成熟し、社会がそれを要求し、本人の準備もできたときに、その課題の学習が最も効果的に進むとされます。これは「レディネス」の考え方にも通じます。ただし、課題の内容は時代や文化によって変わるため、特定の価値観を当てはめて個人を評価するのではなく、成長を支える視点として柔軟に用いる必要があります。",
