    summary:
      "ゲシュタルト心理学者ケーラーがチンパンジーの実験で示した、状況全体を見通して突然に問題を解決する学習。試行錯誤説への対抗理論となった。",
    body: "ヴォルフガング・ケーラー（1887〜1967）はゲシュタルト心理学の創始者の一人で、20世紀初頭にテネリフェ島の類人猿研究施設でチンパンジーの問題解決を観察しました。天井から吊るしたバナナに届くよう木箱を積み上げたり、2本の棒をつないで離れた果物を引き寄せたりする行動が観察され、とくに「スルタン」と呼ばれる個体の事例が有名です。成果は『類人猿の知恵試験』（日本語訳は宮孝一訳、岩波書店）としてまとめられています。\n\nケーラーは、動物がしばらく状況を眺めた後、突然に解決へ至ることに注目し、これを洞察（インサイト）と呼びました。ソーンダイクの問題箱に代表される「試行錯誤による漸進的な学習」とは異なり、道具と目標の関係を全体として捉え直す「見通し」が成立すると考えたのです。いわゆる「ひらめき」や「なるほど」という体験は、この考え方と結びつけて説明されます。\n\n教育への示唆として、知識を断片的に暗記させるのではなく、問題の構造を理解させることの重要性が挙げられます。発見学習や問題解決学習は、学習者自身が関係を見抜く経験を重視する点で洞察学習と親和的です。一方、洞察は何もないところから生じるのではなく、それまでの経験や知識を土台にします。教師は十分に考える時間と手がかりを用意することが大切です。",
