    body: "満足の遅延とは、目の前の小さな報酬を我慢して、後でより大きな報酬を得る能力のことです。ウォルター・ミシェル（1930〜2018）らは1960年代末から1970年代にかけて、スタンフォード大学付属の保育園でこの能力を調べる一連の実験を行いました。子どもの前にお菓子（マシュマロなど）を置き、「待てば2つもらえる」と伝えて、どのくらい待てるかを観察する課題が、いわゆるマシュマロ・テストです。\n\n実験の重要な発見は、待てるかどうかが意志の強さだけでなく、状況や方略に左右されることでした。報酬が目の前に見えていると子どもは早く我慢できなくなり、楽しいことを考えるなど注意をそらす工夫をすると待ち時間が大きく延びました。また、幼児期に長く待てた子どもが、のちに学業面などで良好な結果を示すという追跡調査も報告され、自己制御や非認知能力の重要性を示す例として広く紹介されました。\n\nその後、2018年にワッツ、ダンカン、クアンらが、より大規模で多様な家庭背景をもつ子どもたちのデータで再検討しました。その結果、待ち時間と後の学業成績の関連は元の報告より弱く、家庭背景や早期の認知能力を考慮するとさらに小さくなりました。子どもが待てるかどうかは、周囲の大人への信頼や家庭の経済的な安定にも影響されると考えられています。自己制御を個人の資質だけに帰さず、育つ環境を整える視点が必要です。",
