    body: "防衛機制は、受け入れがたい衝動や感情、現実の苦痛から生じる不安を和らげ、心の安定を保つために、本人が意識しないまま働く心理的なはたらきです。ジークムント・フロイトが精神分析の中で着想し、娘のアンナ・フロイトが『自我と防衛機制』（1936年）で体系的に整理しました。自我が不安に対処するための方法として、さまざまな種類が記述されています。\n\n代表的なものには、苦痛な記憶や衝動を意識から締め出す「抑圧」、もっともらしい理由で自分を正当化する「合理化」、本心と反対の態度をとる「反動形成」、自分の望ましくない感情を他者のものとみなす「投影」、幼い段階の行動に戻る「退行」、衝動を社会的に価値のある活動へ振り向ける「昇華」などがあります。これらは誰もが日常的に用いるもので、それ自体は病的なものではありません。\n\n教育の現場では、子どもの問題行動の背景理解に役立ちます。たとえば、下の子が生まれて急に甘えるようになった児童は退行を示しているのかもしれませんし、攻撃的な態度の裏に不安や劣等感が隠れていることもあります。ただし、防衛機制の解釈は推測にとどまりやすいため、教師が決めつけて分析するのではなく、行動の背景を理解する一つの視点として用い、必要に応じてスクールカウンセラーなど専門家と連携することが大切です。",
