    body: "傍観者効果は、助けを必要とする場面に居合わせた人が多いほど、個々人が援助に踏み出す確率が下がる現象です。1964年にニューヨークで起きた女性殺害事件の報道をきっかけに、ビブ・ラタネとジョン・ダーリーが実験的研究を進め、1968年の論文などで報告しました。ある実験では、部屋に煙が入ってくる場面で、一人でいた参加者の多くが通報したのに対し、反応しない他者と一緒にいた参加者の通報率は大きく下がりました。\n\n主な説明は2つあります。一つは「責任の分散」で、周囲に他者がいると、自分が行動する責任が薄まったように感じるというものです。もう一つは「多元的無知」で、他者が動かないのを見て「大したことではないのだろう」と互いに誤って判断し合うというものです。このほか、他人に評価されることへの不安も関係すると考えられています。なお、きっかけとなった事件については、目撃者の人数や状況の報道が誇張されていたという指摘があり、再検討されています。\n\n学校では、いじめの場面で多くの子どもが傍観者になる現象を理解する手がかりになります。いじめの四層構造論で示される「観衆」や「傍観者」の存在は、被害の継続に影響します。対策としては、この現象を子どもに教えること、「誰か」ではなく特定の誰かに助けを求める方法を学ぶこと、先生や相談窓口に知らせることを望ましい行動として示すことが有効とされます。",
