    body: "アンダーマイニング効果は、自発的に楽しんで行っていた活動に対して、報酬を与えることで、その活動への内発的な興味が弱まってしまう現象です。「過正当化効果」とも呼ばれ、報酬という外的な理由が加わることで、「自分は報酬のためにやっている」と行動の理由を解釈し直してしまうという帰属の変化から説明されます。\n\n代表的な研究に、レッパー、グリーン、ニスベットが1973年に『Journal of Personality and Social Psychology』に発表した実験があります。もともと絵を描くことが好きな幼稚園児を、「上手に描けたら賞状がもらえる」と事前に告げられた群、予告なしに賞状をもらった群、賞状のない群に分けて比較しました。その後の自由時間に、賞状を予告された群の子どもは、他の群よりもマーカーで描く活動への関心が低くなりました。これに先立ち、デシも1971年にパズル課題を用いた実験で同様の傾向を報告しています。\n\nただし、報酬が常に意欲を下げるわけではありません。予告のない報酬や、有能さを伝える情報的な称賛は、むしろ意欲を支えることがあります。教育では、すでに興味をもっている活動に物質的な報酬を安易に結びつけない、評価を「統制」ではなく「情報」として伝えるといった配慮が重要です。自己決定理論の内発的動機づけの議論と合わせて理解するとよいでしょう。",
