    categories: ["psychology"],
    summary:
      "トーマスとチェスのニューヨーク縦断研究にもとづく気質理論。子どもの生得的な反応様式の違いと、環境との適合の良さ（適合の良さ）を重視する。",
    body: "気質とは、感情や行動の反応の仕方に見られる、生まれつきの個人差を指します。アレクサンダー・トーマスとステラ・チェスは、1956年に始まったニューヨーク縦断研究（NYLS）で141人の子どもを乳児期から追跡し、気質を9つの側面で捉えました。活動水準、周期性（生活リズムの規則性）、接近・回避、順応性、反応の強さ、気分の質、持続性、気の散りやすさ、感覚閾値です。\n\nこれらの組み合わせから、研究では大きく3つの型が示されました。機嫌がよく環境の変化に慣れやすい「扱いやすい子」（約4割）、不規則で感情表出が強く慣れにくい「扱いにくい子」（約1割）、新しい場面でゆっくり慣れていく「立ち上がりの遅い子」（約1割強）です。どの型にも当てはまらない子どもも多くいました。「扱いにくい」といった呼び名は、子ども自身に問題があるかのような誤解を生みやすいため、使用には注意が必要です。\n\n研究の大きな成果は「適合の良さ（goodness of fit）」という考え方です。気質そのものに良し悪しがあるのではなく、子どもの気質と、親や教師の期待・環境の要求との相性が発達の結果を左右するとされます。保育・教育の現場では、新しい環境になじむのに時間のかかる子を急かさず、その子の反応様式に合わせた関わり方を工夫することが、情緒の安定と学びの土台につながります。",
    relatedSlugs: ["big-five-personality", "bowlby", "ainsworth-strange-situation", "hoiku-no-shitsu"],
    isCanonical: true,
