    body: "クルト・レヴィン（1890〜1947）はドイツ出身の心理学者で、のちにアメリカに渡り、実験社会心理学を切り開きました。彼の「場の理論」は、行動（B）は人（P）と環境（E）の関数であるという B＝f(P, E) の考え方で知られます。人と、その人が心理的に体験している環境をあわせたものを「生活空間」と呼び、行動をその全体から理解しようとしました。\n\nレヴィンはさらに、集団を単なる個人の寄せ集めではなく、固有の力が働く「力の場」として捉え、集団の力学（グループ・ダイナミクス）を実験的に研究しました。代表的なのが、レヴィン、リピット、ホワイトによる1939年の研究です。少年たちの集団を、専制的、民主的、放任的な3種類のリーダーシップのもとに置いて比較し、専制的な雰囲気では攻撃性や無気力が目立つといった違いを報告しました。この種の研究は、集団の雰囲気（社会的風土）が子どもの行動に影響することを示すものでした。\n\n教育では、学級を一つの集団として捉え、教師のリーダーシップや学級の雰囲気、集団規範が児童生徒に及ぼす影響を考える基礎になっています。ソシオメトリーによる関係の把握、協同学習、学級経営の研究は、この流れの上にあります。また、レヴィンが重んじた、実践をしながら現実を改善する研究の姿勢（アクション・リサーチ）は、現在の学校改善の研究にも引き継がれています。",
    relatedSlugs: ["sociometry-moreno", "kyodo-gakushu", "parsons-gakkyu-shakai-taikei", "jigsaw-method"],
    isCanonical: true,
