    body: "長期記憶は、容量に限りがなく長く保持される記憶ですが、その中にも性質の異なる種類があります。大きくは、言葉で言い表せる「顕在記憶（宣言的記憶）」と、意識にのぼらずに行動として現れる「潜在記憶（非宣言的記憶）」に分けられます。宣言的記憶はさらに、エピソード記憶と意味記憶に分かれます。\n\nエンデル・タルヴィングは1970年代に、この2つの区別を提唱しました。エピソード記憶は、「昨日の遠足で友達とお弁当を食べた」というように、いつ・どこでという時間や場所の文脈をともなう個人的な出来事の記憶です。意味記憶は、「日本の首都は東京である」「三角形の内角の和は180度である」といった、文脈から切り離された一般的な知識や言葉の意味の記憶です。一方、自転車の乗り方や楽器の演奏、九九の暗唱のように、繰り返しの練習で身につき、体で覚えているような記憶が手続き記憶で、潜在記憶に含まれます。\n\n教育に関しては、学校で習う多くの知識は意味記憶ですが、最初は「あの授業で習った」というエピソード記憶として覚えられ、繰り返しや関連づけを通じて意味記憶へと変わっていく面があります。体験活動や具体的な場面を使った学習が記憶の定着を助けるのは、このためです。技能の習得には、手続き記憶を意識した反復練習が欠かせません。記憶の種類に応じた学習方法を考える手がかりになります。",
