    body: "心理的離乳は、青年期の子どもが、乳児が母乳から離れるように、親への依存や家族の監督から心理的に離れ、自分自身の考えや価値観にもとづいて行動する独立した人間になろうとする試みを指します。アメリカの心理学者レタ・ホリングワースが、1928年の著書『The Psychology of the Adolescent（青年期の心理学）』の中で用いた概念として知られます。日本の教科書では、青年期の発達を説明する用語として頻繁に取り上げられます。\n\nこの時期には、親の意見に反発したり、干渉を嫌がったりする第二次反抗期が現れることが多く、心理的離乳の過程の一つとして説明されます。一方で、子どもの関心の中心は、親から友人や仲間へと移っていきます。ただし、実際には親に頼る面も残っており、反抗と依存の間を揺れ動きながら自立が進むと理解されています。かつては「疾風怒濤」の時期と強調されましたが、現在では、すべての青年が激しい親子の対立を経験するわけではないことも指摘されています。\n\n教育・指導の観点では、青年の反抗を単なる問題行動と受け止めず、自立に向かう発達の自然な過程として理解することが重要です。保護者に対しても、過度な干渉を控えつつ、必要なときには相談できる関係を保つよう助言できます。適度な距離を保ちながら見守る関わりが、自己のアイデンティティの形成を支えます。",
