    body: "成人形成期（エマージング・アダルトフッド）は、ジェフリー・アーネットが2000年の論文『Emerging adulthood: A theory of development from the late teens through the twenties（成人形成期：10代後半から20代にかけての発達理論）』（American Psychologist誌）で提唱した、青年期と成人期の間にある独自の発達期です。主に18歳から25歳前後、広くは20代の終わりまでを指します。\n\nアーネットは、この時期の特徴を5つ挙げました。第一に、恋愛、仕事、世界観についてさまざまな可能性を試すアイデンティティの探求。第二に、住まいや仕事、人間関係が変わりやすい不安定さ。第三に、自分自身に焦点を当てる自己への集中。第四に、自分はもう青年ではないが、まだ完全に大人でもないと感じる「中間」の感覚。第五に、将来への期待が高く、人生を大きく変える機会があるという可能性の感覚です。\n\nこの考え方の背景には、高学歴化や晩婚化、就職・結婚の時期の遅れなどによって、成人としての役割に入るまでに長い準備期間が生じたことがあります。ただし、その現れ方は文化や社会経済的な状況によって異なり、すべての若者に当てはまるわけではありません。大学や専門学校での学びや、進路選択、キャリア教育を考える上で、この時期の若者が試行錯誤を重ね、迷いながら自分を形成していく存在であることを理解する助けとなります。",
