    body: "情動の二要因理論は、スタンリー・シャクターとジェローム・シンガーが1962年に発表した感情の理論です。感情は、身体の生理的な覚醒（心拍の上昇、震えなど）と、その覚醒がなぜ起きたのかについての認知的な解釈（ラベリング）という2つの要因が組み合わさって生じると考えます。生理的な覚醒だけでは感情の種類は決まらず、周囲の状況をどう解釈するかによって、喜びにも怒りにもなるとされます。\n\n有名な実験では、男子大学生にアドレナリンを注射し、ビタミン剤の視力への影響を調べると偽って説明しました。副作用について正確に知らされていない参加者は、覚醒の理由を説明できないため、同じ部屋にいる協力者（サクラ）が陽気に振る舞うか、いらだって怒り出すかに応じて、自分も多幸感や怒りを感じやすくなりました。一方、覚醒の理由を正しく知らされていた参加者は、そうした影響を受けにくくなりました。なお、その後の研究で結果の再現性や理論の適用範囲には議論があります。\n\nこの理論は、教育の場で感情を扱う際のヒントを与えます。試験前の動悸を「緊張で失敗する兆し」と解釈すれば不安が高まりますが、「体が集中する準備をしている」と捉え直すことで、緊張が和らぐ場合があります。感情の再解釈は、感情調整や認知行動療法の基本的な発想とも関連しています。なお、緊張や恐怖の覚醒を恋愛感情と取り違える現象を示した「吊り橋実験」（ダットンとアロン、1974年）も、同様の考え方で説明されます。",
