    body: "井の中の蛙効果は、英語で「Big-Fish-Little-Pond Effect（BFLPE）」と呼ばれ、同じ能力をもつ生徒でも、学力の高い学校や学級に所属するほど、学業に関する自己概念（学業的自己概念）が低くなる現象を指します。ハーバート・マーシュが1987年に『Journal of Educational Psychology』（79巻3号）の論文で報告しました。名前の由来は「小さな池の大きな魚」に例えるところからで、日本語では「井の中の蛙」に対応づけて紹介されることがあります。\n\n背景には、人は自分の能力を評価する際に、周囲の身近な他者と比較するという、フェスティンガーの社会的比較の考え方があります。周りが優秀であれば、客観的な成績は高くても「自分は劣っている」と感じやすくなります。マーシュの研究では、この効果は学業的自己概念では大きく現れる一方、一般的な自己概念や自尊感情にはほとんど現れないことが示されました。この現象は多くの国で繰り返し確認されており、メタ分析でも一貫した負の効果が報告されています。\n\n教育では、選抜的な学校や能力別学級に進んだ生徒が、成績は優秀でも自信を失う可能性があることを示唆します。学力による能力別編成は、上位集団にいる生徒の学業的自己概念を下げ、学習意欲に影響しうることを考慮する必要があります。対策として、他者との比較ではなく、過去の自分との比較や自己の進歩に注目する評価（個人内評価）、グループ内での協力的な活動を重視することが有効とされます。",
    relatedSlugs: ["tracking", "kojinnai-hyoka", "jiko-yuyokan", "self-determination-theory"],
