    body: "系列位置効果とは、一連の学習項目を順不同で再生する際、提示位置によって想起率が変動する現象である。エビングハウスの忘却実験に起源を持ち、二重貯蔵モデルにより体系化された。最初の項目が再生されやすい「初頭効果」と、最後の項目が再生されやすい「親近効果」から成る。\n\n初頭効果は、最初に入力された情報に対して反復や意味づけ（リハーサル）が行われ、長期記憶へ転送されやすいことで生じる。親近効果は、直近の情報が短期記憶に残っているため生じる。一方、中間部の項目は先行と後続の情報から干渉を受けるため、保持が難しく想起率が低下する。\n\n授業設計において、本効果は導入と終末の重要性を示している。授業の冒頭と終わりの時間帯は注意と記憶保持が最も高まるため、最重要の概念や要点のまとめを配置することが効果的である。長時間の講義では小休止を設けて区切りを増やすことで、学習全体の定着度を高められる。",
