    body: "気分一致効果とは、個人の現在の感情状態と一致する感情価を持つ情報が、そうでない情報に比べて符号化や想起を受けやすくなる認知現象である。1980年代に心理学者バウアーらが感情ネットワークモデルにより提唱し、情動と記憶の密接な相互作用を示す中核概念となった。\n\nこの現象は、特定の感情に対応する認知の結節点が活性化し、記憶ネットワーク上で関連する概念や記憶へ興奮が拡散することで生じる。心地よい気分のときは肯定的な体験が思い出されやすく、落ち込んでいるときは失敗体験や不安ばかりが想起され、自己評価や意欲を左右する。\n\n教育現場では、学級の温かい雰囲気づくりが学習成果を左右することを示唆する。威圧的で不安の高い環境では過去の失敗が引き出され、学習に消極的になりやすい。安心感と受容的な学級風土を整えることで、成功体験の想起を促し、課題への主体的な挑戦を支えることができる。",
