    reading: "ふごうかとくていせいげんり（たるゔぃんぐ）",
    kana: "ふ",
    categories: ["psychology"],
    summary:
      "情報を記銘した際の文脈や状態に関する手がかりが、情報を思い出す場面でも存在するときに最も効果的に想起できるという記憶理論。",
    body: "符号化特定性原理とは、情報を覚えた際の文脈や状態に関する手がかりが、思い出す場面にも存在するときに最も想起が促進されるという記憶理論である。認知心理学者タルヴィングらが提唱し、記銘時の文脈と検索時の文脈の一致が記憶の成否を決定づけることを実証した。\n\nこの原理によれば、情報は孤立して記憶されるのではなく、周囲の物理的環境や心理状態と結びついて保持される。どれほど強力な手がかりであっても、記銘時に同時に符号化されていなければ想起の助けにならない。学習時と同じ教室で試験を受けると成績が上がる現象もこれで説明される。\n\n授業実践において、知識を活用文脈から切り離して丸暗記させる弊害を警告している。本番に近い状況で演習を行わせたり、どのような場面で活用する知識かを意識させたりすることが有効である。多様な具体例を通じて教えることで、特定文脈への依存を減らし学習の転移を促せる。",
