    reading: "てつづきてききおくろくせんげんてききおく",
    kana: "て",
    categories: ["psychology"],
    summary:
      "身体や認知の技能に関わり言語化が困難な手続き的記憶と、言葉や事実として意識的に想起できる宣言的記憶に大別される長期記憶分類。",
    body: "手続き的記憶と宣言的記憶の区分は、長期記憶の性質を機能的に分類した理論である。哲学者ライルによる「方法の知識」と「事実の知識」の区別を起源とし、認知心理学や神経科学で体系化された。意識的な想起を伴う顕在記憶と、無意識に発現する潜在記憶の対比でもある。\n\n宣言的記憶は事実や概念に関する知識であり、言語やイメージで意識的に再生できる。海馬が関与し形成は早いが忘却も起こりやすい。一方、手続き的記憶は計算の手順や運動技能などの熟練に関わる記憶である。大脳基底核や小脳が関わり、反復練習で獲得され忘却されにくい。\n\n教育現場では、二つの記憶特性に応じた指導が求められる。概念の理解（宣言的記憶）を促した上で、反復練習により計算手順などを自動化（手続き的記憶化）させることが重要である。基礎技能が自動化されると作業記憶の負担が減り、高度な思考や探究に認知資源を配分できる。",
