    title: "エピソード記憶と意味記憶",
    reading: "えぴそーどきおくといみきおく",
    kana: "え",
    categories: ["psychology"],
    summary:
      "個人の特定の体験や時間・空間の文脈を伴うエピソード記憶と、文脈から独立した普遍的な知識や概念を蓄える意味記憶からなる記憶体系。",
    body: "エピソード記憶と意味記憶の分類は、心理学者タルヴィングが提唱した長期記憶の理論的枠組みである。個人が過去の体験を主観的に思い出す個人的な記憶と、社会的に共有される客観的な知識の体系とを区別し、認知心理学の発展に大きく貢献した。\n\nエピソード記憶は、「いつ、どこで経験したか」という時間や空間の文脈、感情を伴う自伝的記憶である。対して意味記憶は、言葉の意味や歴史的事実など、個人の体験文脈から独立した普遍的知識である。個別具体的な体験が積み重なり抽象化されることで、意味記憶が形成される。\n\n授業実践において、両者の結びつきを活用した指導が推奨される。教科書の抽象的な公式や語句を丸暗記させるのではなく、実験や見学、対話といった生き生きとしたエピソード記憶と関連づけて指導することで、意味記憶としての知識の確実な定着と深い理解が促される。",
    relatedSlugs: ["long-term-memory-types", "bartlett-schema-theory", "levels-of-processing", "situated-learning"],
