    kana: "て",
    categories: ["psychology"],
    summary:
      "過去の出来事ではなく、将来の特定の時点や状況において予定された行動を実行することを覚えておく「未来の記憶」を指す認知機能。",
    body: "展望的記憶とは、過去の出来事を思い出す回顧的記憶とは異なり、「放課後に本を返す」「明日提出物を出す」といった将来実行すべき予定や意図を適切なタイミングで思い出して実行する認知機能である。日常生活の自立や学習管理を支える重要な能力として研究されている。\n\nこの機能は、意図の保持、適切な実行機会の監視、現在行っている作業を中断して予定行動に移るという多段階の処理から成る。時間基準型と事象基準型があり、日常活動に従事しながら意図を保持し続ける必要があるため、前頭葉が司る実行機能や自己制御が深く関与している。\n\n児童生徒の忘れ物や提出遅延は、意欲の低さだけでなく展望的記憶の未成熟が一因となる。連絡帳の活用やチェックリストの作成、机上の整理など、外的な手がかりを環境に配置する指導が効果的である。予定を自己管理する工夫を教えることで、主体的で計画的な学習態度を育成できる。",
