    body: "幼児期健忘とは、成人が3歳から4歳頃までの個人的な出来事をほとんど想起できない現象である。フロイトが抑圧の観点から注目したことに始まり、現代の発達心理学では脳神経の発達や認知の変容に基づく適応的プロセスとして解明が進められている。\n\nこの現象のメカニズムには、幼児期に海馬で神経細胞の新生が活発に起こり記憶痕跡が更新されることや、過去の経験を言語化して物語として整理する言語能力の未熟さが関係している。また、客観的に自己を捉える「自伝的自己」の確立が不十分であることも原因とされる。\n\n教育的示唆として、幼児期の経験が消去されるわけではない点が重要である。個別の出来事は想起できなくても、養育者との温かい関わりや安心感は基本的信頼感として子どもの心に深く根づく。乳幼児期の豊かな愛情や対話は、生涯にわたる人格形成の基盤を育んでいる。",
