    body: "偽りの記憶（虚記憶）とは、実際には起きていない出来事を真実の体験として想起する現象である。認知心理学者ロフタスは、質問の表現や事後情報によって記憶が書き換えられる事後情報効果を実証し、記憶は正確な記録ではなく主観的な再構成物であることを明らかにした。\n\nこの現象は、情報の出どころを識別するモニタリングの失敗によって生じる。他者の示唆や自らの想像によるイメージが、時間の経過とともに実際の知覚記憶と混同される。さらに人間は既存の知識（シェマ）に合致するように記憶の欠落を補うため、誤った記憶に強い確信を抱きやすい。\n\n生徒指導や教育相談において、本理論は重要な教訓を与える。教員が先入観を持って誘導的な質問を重ねると、子どもが意図せず偽りの内容を信じ込んで証言する危険がある。事実確認の際は開かれた質問を用い、記憶の変容可能性に配慮した中立的な姿勢を保つことが求められる。",
