    body: "プロトタイプ理論とは、概念の分類が明確な境界基準ではなく、そのカテゴリーの最も典型的な事例（プロトタイプ）との類似度に基づいて行われるとする認知理論である。ロッシュが提唱し、事物の認識や言語の意味構造の解明に大きな転換をもたらした。\n\n例えば「鳥」という概念において、スズメは典型性が高いため素早く鳥と認識されるが、ペンギンは典型性が低く判断に時間を要する。概念の境界は柔軟であり、事例は中心からの類似度に応じた連続体として捉えられる。人間は適度な情報量を持つ基本水準の概念を好んで用いる。\n\n授業における概念指導に本理論は明快な順序性を示す。未知の概念を教える際は、抽象的な定義から入るのではなく、まず典型的な事例を提示して直感的な理解を促すことが効果的である。その後に例外や境界事例へと比較を広げることで、頑健な概念構造を定着させることができる。",
