    body: "メンタルモデル理論とは、人間の推論や文章理解が形式的な論理規則の計算によるのではなく、状況の構造を頭の中に作業空間として構築することで行われるとする認知理論である。ジョンソン＝レアードが提唱し、思考と理解の具体的メカニズムを明らかにした。\n\nこの理論によれば、人間は前提から可能な状況の具体的な心的モデルを組み立て、それを観察して結論を導き、さらに結論を否定する別の反例モデルがないかを検証する。推論の誤りは論理規則の欠如ではなく、作業記憶の容量を超えて反例の探索に失敗することから生じる。\n\n理科の実験現象や国語の文章読解において、学習者が頭の中に明確なモデルを構築できるよう支援することが重要である。図解や実物模型、視覚的な説明を取り入れることで、抽象的な記述を直感的なモデルに変換でき、思考の負担を減らし本質的な理解へと導くことができる。",
