    body: "アナロジー的思考（類推）とは、よく知っている既知の領域の構造的な関係性を手がかりにして、未知の領域の問題解決や理解を促進する高次認知機能である。ギックやホリオークらの研究により、創造的思考や学習の転移を支える中核メカニズムとして体系化された。\n\nこの思考は、既知事例の想起、二つの領域間における構造的関係の対応づけ、未知事例への知識適用という段階で進む。学習者は外見的な類似性に目を奪われやすく、深層の論理構造の共通性を見落としがちである。多様な事例から共通原理を抽出する経験が類推を円滑にする。\n\n抽象的な概念を教える際、身近なアナロジーを活用する指導が有効である。電流を水流にたとえる指導などが代表例である。ただし、類推には必ず差異点が存在するため、合致しない限界も併せて検討させることが大切である。自ら類推を考えさせる学習は深い転移力を育てる。",
