    body: "ヒューリスティクスと認知バイアスのアプローチは、カーネマンとトベルスキーが確立した意思決定理論である。人間は厳密な論理計算を行うのではなく、直感的な思考の近道（ヒューリスティクス）を用いるため、特定の状況で規則的な判断の偏り（バイアス）が生じる。\n\nこの現象は、直感的で迅速な「システム1」と、論理的で意識的な「システム2」の二重過程で説明される。直感は日常の迅速な判断を支える優れた適応機能であるが、確率や客観的証拠を扱う場面では直感的手がかりに頼りすぎ、誤った推論や偏見を生む原因となる。\n\n教育現場において、児童生徒の批判的思考力の育成に不可欠な視点を提供する。自らの直感が誤りに陥りやすい特徴を理解させることで、証拠に基づいて多角的に検証する探究的な態度が育つ。教師自身も評価において自らの偏向を自覚し、公平な視点を保つことが求められる。",
