    body: "利用可能性ヒューリスティックとは、事象の頻度や確率を判断する際、客観的な統計データではなく記憶からの「思い出しやすさ」を手がかりにして判断する認知的近道である。トベルスキーとカーネマンが実証し、人間の直感的な確率判断の特徴を明らかにした。\n\n感情を強く動かされた出来事や報道で大きく取り上げられた事例は、記憶から容易に想起される。そのため、実際の発生確率は極めて低いにもかかわらず発生率を過大評価し、逆に身近で想起しにくい事象を過小評価してしまう。想起の鮮明さと客観的頻度の混同が原因である。\n\n学習指導において、感情的な思い込みを排しデータに基づいて論理的に判断する態度の育成につながる。生徒が主観的な印象だけで判断する際、客観的な数値や統計を示して比較させる指導が有効である。メディア情報に惑わされず冷静に証拠を吟味する力を育てることができる。",
