    body: "代表性ヒューリスティックとは、ある事象が特定のカテゴリーに属するかどうかを、その典型的なイメージにどれだけ似ているかに基づいて直感的に判断する思考法である。カーネマンとトベルスキーにより提唱され、確率判断における直感の偏りを説明する概念となった。\n\nこの思考法では、対象の特徴が典型例と一致すると、母集団における基準率を無視して確率を高く見積もってしまう。また、コイン投げの連続で規則的な並びを不自然と感じる錯覚も、典型的な無作為性のイメージに合致しないことから生じる誤った直感の表れである。\n\n教育実践において、固定観念の打破や統計的思考力の育成に示唆を与える。外見や一部の行動から生徒の性格や学力を短絡的に決めつける偏見を防ぐ指導に生かせる。数学や探究活動において、直感の誤りを客観的データや論理的思考で修正する科学的態度を養うことができる。",
