    body: "ギルフォードの知能構造モデル（SIモデル）とは、人間の知能を単一の尺度ではなく多面的な能力の立体マトリクスとして体系化した理論である。ギルフォードが提唱し、従来の知能検査が見落としていた創造性や拡散的思考の重要性を教育界に広めた。\n\nこのモデルは知能を3次元で整理する。思考の対象である「内容」、認知的処理を行う「操作」、処理の結果生じる「所産」である。これらを掛け合わせ最大180種の能力を定義した。特に、唯一の正解を求める「収束的思考」に対し、柔軟に多様な案を生む「拡散的思考」を創造性の基礎とした。\n\n正解の暗記に偏りがちな指導を見直し、多角的な発想力や創造的表現力を育む重要性を提起している。探究学習において、既存の枠にとらわれず多様な解決策を発想させる拡散的思考の機会を設けることで、子どもたちの潜在的な創造性を引き出し、豊かな思考力を育てることができる。",
