    body: "アメリカの心理学者レイモンド・キャッテルは、知能の構造を因果的に解明する中で、生得的な神経学的基盤に基づく「流動性知能」と、学習や文化的経験によって蓄積される「結晶性知能」の二因子を提唱し、両者の発達的連関を示す投資理論を展開した。\n\nこの理論では、新しい環境や課題に直感的に適応する流動性知能を、学校教育や日々の実践活動という学習機会へ投資することを通じて、言語能力や専門的技能といった結晶性知能が体系化されると捉える。流動性知能は青年期に成熟の頂点を迎えて加齢とともに低下するが、投資によって獲得された結晶性知能は成人期以降も維持され、経験を重ねることで向上し続ける。\n\n教育現場への示唆として本理論は、発達初期に良質で多様な認知的刺激を与え、生得的な知的潜在力を効果的な学習へと結びつける教育環境の重要性を説く。基礎的な思考力や探究の意欲を適切な学習活動に投資させることが、生涯にわたる知的発達の土台となる。",
