    body: "二十世紀初頭のフランスにおいて、心理学者アルフレッド・ビネーと医師テオドール・シモンは、初等教育の義務化に伴い、普通教育での学習に適応が困難な児童を客観的に見出すため、世界で最初の実用的な知能検査を開発した。\n\n従来の感覚検査とは異なり、判断力や理解力、論理的思考といった高次精神機能を重視した課題を設定した点が特徴である。年齢段階ごとに達成可能な課題を体系的に配置し、児童が合格した課題水準から「精神年齢」を算出することで、暦年齢との差に基づいて発達の遅滞度を評価する革新的な測定法を確立した。\n\nビネーらの意図は知能による児童の選別や固定化ではなく、教育的な援助を必要とする子どもに適切な特別支援を提供することにあった。この理念は現代の教育診断や個別指導計画の出発点であり、個々の発達特性に寄り添った学習支援の道を開いた。",
