    body: "アトキンソンとシフリンが提唱した記憶の二重貯蔵モデルにおいて、情報の入力口に位置づけられるのが感覚記憶である。人間が五感を通じて外界から受け取る膨大な情報は、まずこの感覚受容器の貯蔵庫に一時的に保持される。\n\n感覚記憶は対象の物理的特徴をありのままに保持する大容量の記憶であるが、その持続時間は極めて短い。視覚情報に関する「アイコニック記憶」は一秒未満で速やかに減衰し、聴覚情報に関する「エコーイック記憶」は音韻の連続性を把握するため数秒間保持される。この段階で意識的な注意を向けられた情報のみが短期記憶へと転送され、高次の処理へと進む。\n\n教育現場における指導では、学習者の感覚記憶から短期記憶への情報移行を確実にするため、提示する教材の視覚的強調や音声の区切りを工夫することが重要である。児童生徒の注意を適切に誘導し、不要な雑音や刺激を低減させることが、効果的な学習成立の鍵となる。",
