    body: "初期の行動主義心理学では、心理学を客観的な自然科学として確立するため、観測可能な「刺激（S）」と「反応（R）」の結びつきのみを対象とするS-R理論がワトソンらによって推進された。生体の内面は「ブラックボックス」として排除されていた。\n\nこれに対しウッドワースやトールマンらは、同一の刺激に対しても主体の状態によって反応が異なる事実を指摘し、刺激と反応の間に「有機体・生体（O）」の内的な媒介過程を組み込むS-O-R理論を提唱した。学習とは単なる機械的な連合形成ではなく、生体が持つ欲求、目標、仮説、認知的構図などの内的要因によって変容する能動的な過程であると捉え直された。\n\nこの視点の転換は現代の学習指導に強い影響を与えている。画一的な反復演習にとどまらず、学習者が事象をどのように解釈し、どのような動機を持って課題に向き合っているかという主体的・内面的な状態を把握し、それに応じた指導を展開することが重視されている。",
