    body: "バラス・スキナーが創始したオペラント条件づけにおいて、行動がどのような頻度や間隔で強化されるかを体系化した枠組みが「強化スケジュール」である。すべての反応を強化する連続強化に対し、一部の反応のみを強化する間欠強化の法則性を解明した。\n\n間欠強化は「固定比率（FR）」「変動比率（VR）」「固定間隔（FI）」「変動間隔（VI）」の四形態に大別される。一定の反応数ごとに強化する固定比率では達成直後に休止が生じやすいのに対し、平均的な反応数で予測不能に強化する変動比率は極めて高い反応率と消去に対する強い抵抗力を生み出す。時間経過に基づく間隔スケジュールも学習の安定性に特有の効果をもたらす。\n\n学校教育の実践において本理論は、新しい学習習慣の定着と自立的な持続を促す指針となる。導入期には連続強化で確実な成功体験を与え、学習が軌道に乗った段階で間欠強化へと移行することで、賞賛や外部報酬への依存を減らし、自発的・持続的な学習態度へと発展させることができる。",
