    reading: "しょうきょとじはつてきかいふく（じょうけんづけのへんよう）",
    kana: "し",
    categories: ["psychology"],
    summary:
      "強化刺激の停止により条件反応が衰退・消失する「消去」と、休止期間の後に再び条件反応が一時的に再出現する「自発的回復」という条件づけの変容現象。",
    body: "古典的条件づけおよびオペラント条件づけにおいて、獲得された行動が環境の変化に応じてどのように弱まり、あるいは再燃するかを解明したのが「消去」と「自発的回復」の概念である。\n\n獲得された条件反応に対して無条件刺激や強化子の提示を取りやめると、条件反応の生起頻度は徐々に減少し、やがて生起しなくなる。これが消去である。しかし消去が完了した後に一定の休止期間を置き、再び刺激を提示すると、追加の強化なしに条件反応が一時的に復活する現象が見られ、これを自発的回復と呼ぶ。この事実は、消去が記憶の完全な喪失ではなく、新たな抑制的学習であることを示している。\n\n生徒指導や特別支援教育において本原理は極めて重要である。授業中に不適切な行動で注目を集めようとする児童に対して注目を避ける消去を適用する際、一時的な反発や自発的回復による再出現を予期し、一貫した態度で望ましい代替行動を強化し続ける冷静な対応が求められる。",
