    body: "学習心理学において、生物が環境内の多様な情報に適応するための相反的かつ補完的なメカニズムが「刺激般化」と「弁別学習」である。パブロフやその後の行動主義研究者たちによって体系化された。\n\n刺激般化とは、特定の条件刺激に対して条件反応を獲得した後、その刺激に類似した別の刺激に対しても同様の反応が引き出される現象を指す。類似性が高いほど反応は強くなる。これに対し弁別学習は、特定の刺激には強化を与え、類似した他の刺激には強化を与えない訓練を通じて、刺激間の差異を正確に識別し、適切な反応を分化させる過程を意味する。\n\n学校現場において両者は、概念形成や基礎学力の習得に深く関わっている。児童が「犬」という概念を様々な種類の犬に適用できるのは般化の働きであり、犬と猫の違いを正しく見分けるのは弁別学習の成果である。教師は適切な具体例と反例を提示し、児童の的確な弁別と般化を導く指導が求められる。",
