    body: "心理学者デイビッド・プレマックが提唱した「プレマックの原理」は、何が強化子として機能するかを行動の生起確率の差に基づいて定義した画期的な学習理論である。「おばあちゃんの知恵」としても知られている。\n\n本原理では、強化子を単なる物質的報酬ではなく「活動そのもの」として捉える。自由な状況下で個体が自発的に行う頻度の高い活動（高確率行動）と、あまり行わない活動（低確率行動）が存在する場合、低確率行動を行った直後に高確率行動に従事できる随伴性を設定すると、低確率行動の頻度が増加するという力学を明らかにした。\n\n学校教育や家庭学習において本原理は、学習意欲の向上に極めて有効である。「計算ドリルを終えたら読書や図画工作をしてよい」といった約束を設定することで、外部からの物質的報酬に頼ることなく、学習者の自発的な活動を自然な動因として学習習慣を定着させることができる。",
