    body: "オペラント心理学の消去および強化の原理に基づく「タイムアウト法」は、児童の破壊的行動や攻撃行動などを安全かつ効果的に低減させるための環境調整的な行動修正技法である。\n\nこの手法は、不適切な行動が周囲の注目や刺激などの「正の強化子」によって維持されている場合、その行動が生起した直後に学習者を強化刺激が存在しない静かな空間へと短時間移動させる。刺激への接近を遮断することで行動の機能的意味を失わせるとともに、高揚した情動を沈静化させる機会を提供する。体罰や精神的威圧を用いることなく行動を修正できる点に科学的意義がある。\n\n教育実践において適用する際は、事前の約束や短時間の実施（児童の年齢に応じた数分程度）、および落ち着いた後の望ましい行動に対する再度の肯定的な関わりが不可欠である。単なる排除や懲戒ではなく、自己統制を促す支援的な枠組みとして運用することが求められる。",
