    body: "行動分析学の原理を組織的・社会的に応用した「トークン・エコノミー法」は、条件性強化子の働きを利用して望ましい行動の定着を促進する構造的な行動変容システムである。\n\nこの技法では、標的とする望ましい行動（着席、課題提出、協調的態度など）が達成された際、シールやカード、点数といった直接的な価値を持たない「トークン」を直ちに手渡す。学習者は集めたトークンを、一定期間の後に自由時間や好みの活動といった「交換強化子」と引き換えることができる。即時的なフィードバックと中長期的な動機づけを架橋する点が強みである。\n\n学校現場や特別支援学級において本手法は、学習規律の確立や生活習慣の改善に広く用いられている。児童生徒の自律的な目標達成意欲を刺激する効果がある一方、過度な外的報酬への依存を避けるため、徐々に社会的賞賛や内発的達成感へと移行させる指導計画が大切である。",
