    body: "行動主義心理学者スキナーによって体系化された「シェイピング法（漸次的接近法）」は、対象者の行動レパートリーに存在しない新しい複合的行動を、段階的かつ無理なく習得させるための基本的な訓練技法である。\n\nこの手法では、最終目標となる行動を細かく要素分解し、現時点で実行可能な類似行動から出発する。最初の段階の反応が生起した際に即座に強化を与え、定着したら次の基準へと強化の要求水準を引き上げる。前の段階の行動は強化せず、より目標に近い新しい行動のみを選択的に強化することで、目標行動へと徐々に接近させていく。\n\n教育や特別支援の実践においてシェイピングは、つまずきを抱える児童生徒に対する「スモールステップの指導」の論理的根拠となっている。過大な要求による失敗経験を防ぎ、小さな成功体験を積み重ねさせることで、学習意欲と自己肯定感を育みながら確実な技能習得を実現できる。",
