    body: "応用行動分析における「チェイニング法（連鎖化技法）」は、独立した個別の行動単位を前後の文脈に従って連続的に結びつけ、一つの統合された複雑な行動連鎖を形成する指導手法である。\n\n本技法ではまず、一連の作業手順を細かな行動単位へと分析する課題分析を行う。最初の手順から順に教えていく「順行チェイニング」と、最後の手順から遡って指導し達成感を直後に味わわせる「逆行チェイニング」がある。各行動の完了が次の行動の合図（弁別刺激）となり、同時に直前の行動の強化子として機能することで、一連の流れが強固に定着する。\n\n学校教育や特別支援教育において本技法は、衣服の着脱や手洗い、給食当番の準備、実験器具の操作といった一連の生活動作・学習作業の自立支援に不可欠である。段階的に支援を減らしていくことで、児童生徒が自立して一連の行動を完遂できるよう導く。",
