    body: "心理学者アルバート・バンデューラは、人間が他者の行動とその結果を観察するだけで新しい行動を獲得できる事実を解明し、従来の刺激反応理論を超越する社会的学習理論を樹立した。\n\n観察学習が成立する過程は「注意過程」「保持過程」「運動再生過程」「動機づけ過程」の四段階からなる。まずモデルの行動に注目し（注意）、その情報を言語や心像の形で記憶として蓄え（保持）、自己の身体運動を用いて忠実に再現し（運動再生）、期待される成果や自己効力感によって行動を実行に移す（動機づけ）。単なる機械的模倣ではなく、高度な認知処理が介在する点に特徴がある。\n\n学校教育において本理論は、教師や仲間の望ましい姿が持つ教育的影響力を明確に示している。児童生徒の関心を引きつけ、分かりやすく手順を言語化し、練習の機会と肯定的な評価を与える一連の指導計画を設計する指針として広く活用されている。",
