    body: "バンデューラの社会的学習理論において、個人の行動調整を説明する中核的な概念が「代理強化」と「自己強化」である。直接的な賞罰を経験しなくても行動が学習される社会的メカニズムを明らかにした。\n\n代理強化とは、観察対象であるモデルが特定の行動によって賞賛や報酬を獲得する、あるいは非難や罰を受ける様子を見ることで、観察者自身のその行動の生起頻度が増減する現象を指す。一方、自己強化は他者からの外的な報酬に依存せず、自己が設定した行動基準に照らして自らの成果を評価し、誇りや満足感といった内的な報酬を自身に与える機制である。\n\n学級経営や生徒指導において教師は、模範的な行動を適切に評価することで学級全体への代理強化を促すことができる。さらに指導の最終目標として、他者の顔色をうかがう行動から脱却し、自らの達成基準に基づいて努力を継続できる自己強化の力を児童生徒に育てることが重視される。",
