    body: "社会心理学や健康心理学において、個人がストレスフルな環境に適応する際の重要な資源として研究されてきたのがソーシャル・サポートである。ハウスらは他者から受ける多様な援助行動を四つの機能に整理した。\n\n第一は共感、受容、愛情を提供して安心感をもたらす「情緒的サポート」、第二は本人の価値を肯定し適切なフィードバックを与える「評価的サポート」、第三は問題解決に必要な助言や知識を提供する「情報的サポート」、第四は物資や労力などの具体的支援を直接提供する「道具的サポート」である。これらが複合的に機能することで、ストレスの悪影響を低減する緩衝効果が発揮される。\n\n学校現場において本理論は、児童生徒の不登校や孤立を防ぐ教育相談体制の構築に直結している。教師、養護教諭、専門職や地域が連携し、子どもが多面的な支援を実感できる温かい学校風土を形成することが、児童の精神的健康の向上につながる。",
