    body: "フロイデンバーガーが提唱しマスラックが尺度化した「バーンアウト（燃え尽き症候群）」は、教育や医療などの対人援助職において、献身的な努力の果てに極度の疲弊へと陥る心理的破綻状態である。\n\nマスラックの理論では三つの下位因子が定義されている。第一に感情のエネルギーが完全に枯渇する「情緒的消耗感」、第二に相手に対する思いやりを失い事務的で冷淡な態度をとる「脱人格化」、第三に自己の教育的働きかけに有能感を感じられなくなる「個人的達成感の低下」である。理想と現実の落差や過度の業務負担が複合して進行する。\n\n教員の多忙化や精神疾患による休職が深刻化する現代の教育現場において、バーンアウトの予防は喫緊の課題である。個人のストレス管理に委ねるだけでなく、学校組織としての業務分担の是正や同僚同士の支援的関係の再構築など、構造的な職場環境の改善が不可欠である。",
