    body: "リチャード・ラザルスらが提唱した心理的ストレスの認知的評価モデルにおいて、ストレス事態の負荷を軽減するために個人が能動的に用いる工夫や戦略を「コーピング（対処行動）」と呼ぶ。\n\n個体は外界の刺激に対し、自身への影響を判断する一次的評価と、利用可能な対処資源を吟味する二次的評価を行う。それに基づいて選択されるコーピングは、ストレッサーの根本的解決や環境改善を試みる「問題焦点型コーピング」と、生じた不安や怒りなどの興奮を沈静化させ認知を再構成する「情動焦点型コーピング」に大別される。状況の変革可能性に応じた柔軟な使い分けが適応の鍵となる。\n\n学校教育においてストレスマネジメント教育の一環としてコーピング学習を導入することは有益である。児童生徒が試験不安や対人摩擦に直面した際、自らの感情に気づき、多彩な対処選択肢から状況に応じた適切な方法を選び取る力を育成できる。",
