    body: "臨床心理学や精神医学において不適応の発症メカニズムを包括的に説明する枠組みが「素質-ストレスモデル」である。疾患の発生を個人の素質のみ、あるいは環境要因のみに還元せず、双方の相互作用として捉える。\n\nこの仮説では、個人が潜在的に持つ遺伝的素因、気質、初期成育環境で形成された心理的弱点などの「素因」と、生活環境の中で遭遇する過重な心理社会的「ストレス」の組み合わせを考える。素因が大きい個人はわずかな環境ストレスでも適応困難に陥りやすい一方、素因が小さい個人は強いストレスにさらされても安定を保ちやすい。\n\n教育現場における児童理解において本モデルは、子どもの困難を単なる努力不足や怠惰として片付けない視座を提供する。生徒の個別の敏感さや素因に配慮した指導を行うとともに、学校環境における過度なプレッシャーを低減させ、保護的要因を増やす支援が求められる。",
