    body: "生理学者ハンス・セリエは、生体が多様な有害刺激（ストレッサー）に直面した際、刺激の種類を問わず共通して示す生体反応を発見し、これを「汎適応症候群」として体系化した。現代のストレス理論の出発点となった。\n\n生体の適応反応は「警告反応期」「抵抗期」「疲弊期」の三段階を経る。最初の警告反応期ではショックによる生体機能の低下後に緊急防衛態勢が敷かれる。続く抵抗期では自律神経や内分泌系が活発に働きストレッサーとの均衡を維持するが、刺激が長期化すると適応エネルギーが枯渇し、最後の疲弊期へと至って心身の崩壊や深刻な不適応を招く。\n\n学校現場において本理論は、長期間にわたる過密日程や試験、対人葛藤が児童生徒の心身に与える影響を理解する上で重要である。表面上は適応しているように見えても抵抗期にある子どもを見逃さず、疲弊期に達する前に休養や環境調整を促す保健指導が求められる。",
