    body: "発達心理学者エリクソンが提唱したライフサイクル論において、青年期（第5段階）の発達課題として位置づけられたのが「アイデンティティ（自我同一性）の確立」と「同一性拡散」の対立である。子どもから大人への移行期における激しい自己探求の葛藤を説明した。\n\n青年は身体的成熟や社会的役割の拡大に直面し、「自分は何者か」「将来どう生きるべきか」という問いを抱く。過去・現在・未来を通じた自己の連続性や社会における居場所を見いだすことで確固たる自己同一性を獲得するが、これに失敗すると自己喪失感や無気力などの同一性拡散に陥る。\n\n中等教育や高等教育の実践においては、生徒が多様な価値観に触れ、失敗を恐れずに自己の興味関心を追求できる心理社会的モラトリアムの保障が不可欠である。進路指導やキャリア教育を通じ、自己理解と社会的自立を温かく支える学習環境の構築が求められる。",
