    body: "第二反抗期は、思春期・青年期前期に見られる保護者への激しい反発や否定的な態度の高まりを指し、幼児期の第一反抗期と対比される。ホルリングワースが提唱した心理的離乳の概念と密接に関わり、親への依存から精神的な自立へと移行する不可欠な発達段階である。\n\n第二次性徴に伴う急激な心身の変化の中で、青年は自己の内面的な自律性を求めるようになる。親の干渉や価値観を一方的に受け入れることを拒絶し、反抗や口論を通じて親からの心理的境界線を確立しようとする。この葛藤と脱同一化を経て、親を一人の不完全な人間として客観的に捉え直す。\n\n学校教育や家庭支援においては、反抗を単なる問題行動として処罰するのではなく、自立に向けた健全な通過儀礼として受容する姿勢が大切である。教師や保護者は過度な管理や支配を慎み、対等な人間として青年の自己決定を尊重しながら見守る関わりが求められる。",
