    body: "社会学者パークが異文化接触の中で提唱した境界人（マージナル・マン）の概念を、ドイツ出身の心理学者クルト・レヴィンは青年期の発達心理学的特徴を解明するために援用した。子どもでもなく大人でもない過渡期にある青年の不安定な心理状態を鮮やかに描写した。\n\nレヴィンの場理論によれば、青年は子どもの生活空間を離れつつあるが、大人の生活空間への完全な所属も許されていない境界領域に置かれている。所属集団の基準があいまいであるため、情緒的な動揺、過度な過敏性、自己矛盾、極端な行動の揺らぎといった特有の緊張や葛藤が生じやすい。\n\n中等教育現場では、生徒が抱く所在のなさや居心地の悪さを理解し、安心して所属できる学級や部活動などの場を整えることが欠かせない。青年の過敏な言動を受け止めつつ、社会の責任ある一員として参画できる多様な役割を任せる実践が精神的成熟を促す。",
