    body: "アメリカにおける心理学の先駆者であるスタンレー・ホールは、1904年の大著『青年期』において、思春期から青年期にかけての時期をドイツの文学運動にちなんで「疾風怒とう（シュトゥルム・ウント・ドラング）」の時代と規定した。青年期を独立した発達段階として確立した。\n\nホールは個体発生は系統発生を繰り返すという反復説に基づき、青年期を野蛮から文明への飛躍的移行期とみなした。この時期の青年は、高揚と憂うつ、利他性と利己性、従順と反抗といった激しい感情の両極端を揺れ動き、心身の急激な変化に伴う激甚な内的動揺を経験すると説明した。\n\nホールの理論は近代的な青年期観を形成し、中等教育制度の整備や課外活動の重要性を喚起する契機となった。現代の教育実践においても、思春期特有の情緒不安定や反抗を病理視せず、人間的成長のための創造的なエネルギーとして肯定的に受け止める指導が求められる。",
