    body: "アメリカの心理学者マーティン・ホフマンは、道徳性の発達と向社会的行動の動機づけにおける核心として共感性に着目し、その生涯にわたる発達段階理論を構築した。情動的な反応と認知的発達の統合過程として共感の深化を説明した。\n\nホフマンは共感を4段階に整理した。新生児の泣き声の伝染に見られる「全体的共感」、自己と他者の身体を区別し始める「自己中心的一般的共感」、他者が独自の感情を持つことを理解する「他者の感情に対する共感」、そして他者の生涯の生活境遇や苦難に思いを寄せる「他者の生活状況に対する共感」である。\n\n学校の道徳教育や生徒指導では、単に規則を教え込むのではなく、他者の立場や心情を想像させる受容的な問いかけが共感性の向上に寄与する。困難な立場にある他者の状況に触れる体験活動や読書活動を取り入れることで、成熟した利他的行動を促すことができる。",
