    body: "前向性健忘と逆行性健忘は、頭部外傷、脳血管障害、海馬の損傷、あるいは強い心理的ショックによって引き起こされる記憶機能障害の代表的な分類である。記憶の固定化や想起に関わる神経基盤を解明する認知心理学や神経心理学の研究において極めて重視される。\n\n前向性健忘は、発症以降に経験した新たな情報を長期記憶として定着させることができなくなる障害である。一方、逆行性健忘は、発症以前に保持していた過去の記憶を思い出すことができなくなる状態を指す。健忘症患者の研究により、短期記憶から長期記憶への移行や記憶の固定化過程の存在が証明された。\n\n教育現場においては、頭部外傷を負った生徒や認知の困難を抱える学習者に対する特別な配慮を理解する基礎知識となる。新しい学習事項が定着しにくい特性に対しては、視覚的手がかりや外部の記録器具を活用し、反復と確認を丁寧に重ねる支援設計が求められる。",
