    body: "イギリスの認知心理学者コリン・チェリーが1953年に提起したカクテルパーティー効果は、パーティー会場のような騒音の中でも特定の会話に集中して聞き取れる現象である。人間の感覚器官に入力される膨大な情報から必要な対象を選び出す選択的注意の存在を示した。\n\nブロードベントのフィルター理論やトリーズマンの減衰理論などの注意モデルによって説明された。人間は物理的な音の方向や声の高さだけでなく、自己の名前や関心のある単語といった意味的な重要性を無意識下で瞬時に分析し、必要な情報へと注意の資源を傾ける情報処理機構を備えている。\n\n授業や学習指導において、教師が生徒の興味を引くキーワードを冒頭に提示したり名前を呼びかけて意識を向けさせたりする技法の根拠となる。また、教室内の不要な騒音や視覚的刺激を減らし、注意が散漫になりやすい生徒が学習対象に集中できる環境調整も重要である。",
