    body: "アメリカの心理学者ジョン・リドリー・ストループが1935年に発表したストループ効果は、相矛盾する二つの情報が同時に提示されたときに生じる認知処理の遅延現象である。無意識に行われる自動的処理と意識的な統制処理の競合を実証した実験として広く知られる。\n\n実験では、例えば「あか」という文字が青いインクで印刷されている場合、インクの色（青）を答える課題において、文字を読むことと色を識別することの間で干渉が起き、反応時間が著しく遅れる。高度に熟達した文字の読み処理が意図せず自動的に作動し、色の命名という統制的な課題を妨害するためである。\n\n学習指導においては、基礎的な技能が自動化されることの重要性と、慣れ親しんだ枠組みが新たな課題の遂行を妨げる干渉現象の双方を理解する手がかりとなる。教材の提示では不要な視覚的矛盾を排除し、学習者の認知負荷を軽減して課題の本質に集中させる配慮が求められる。",
