    body: "変化盲と非注意性盲目は、人間が視野内のあらゆる刺激を均等に知覚しているわけではないことを実証した認知心理学の概念である。サイモンズとチャブリスによる有名な実験などを通じ、視覚意識と注意配分の密接な連動関係が鮮やかに証明された。\n\n変化盲は、視界の遮断やまばたきの瞬間に生じた情景の変化に気づけない現象である。一方、非注意性盲目は、特定の課題に注意を集中させていると、視覚領域の中央に現れた予想外の対象をまったく知覚できない現象を指す。これらは人間の視覚認知が極めて限定的な注意資源に依存していることを示す。\n\n授業実践では、板書やスライドの変更点について教師が「見ればわかる」と過信せず、注目すべき箇所を指し示したり言葉で明示したりする指導が不可欠である。視覚教材を用いる際は要点を絞り、学習者の注意が散漫にならない提示の工夫が求められる。",
