    body: "プライミング効果は、あらかじめ見聞きした先行刺激（プライム）が、その後に提示される目標刺激の処理効率や解釈を無意識のうちに左右する認知現象である。潜在記憶研究の発展とともに解明が進み、意味ネットワーク理論の妥当性を示す実証的根拠となった。\n\n同じ刺激の反復による知覚的プライミングと、概念の連想に基づく意味的プライミングに大別される。例えば「医者」という単語を読んだ直後は「看護師」という語の認知判断が速くなる。先行刺激によって長期記憶内の関連概念が活性化し、その興奮が近隣のノードへと拡散するためである。\n\n授業の導入段階で前時の復習を行ったり関連する身近な話題を提示したりする工夫は、まさに生徒の認知枠組みを活性化させる実践的なプライミングである。適切な背景知識を呼び覚ますことで、新しい学習内容の理解が促進され、認知的負担を大幅に軽減できる。",
