    body: "子どもは学校で正式に学ぶ前から、日常生活の経験を通じて事物や世界の仕組みに関する直観的な説明体系（素朴理論）を形成している。概念変化とは、この素朴理論と科学的概念との矛盾を解消し、より高次の概念枠組みへと抜本的に組み替える認知過程を指す。\n\nポズナーらの理論によれば、学習者が既存の素朴理論に不満を感じ、新たな科学的概念が理解可能で妥当であり、さらに新しい現象を説明する上で有効であると認識されたときに概念変化が生じる。単なる知識の追加ではなく、根本的な信念構造の組み替えが要求される。\n\n理科教育や社会科教育では、教科書の正解を暗記させるだけでは素朴概念の打破は困難である。学習者の持つ素朴理論を対話や予測によって顕在化させ、矛盾する実験事実を提示して認知的不協和を生起させる探究的な問題解決学習が有効である。",
