    body: "誤概念（ミスコンセプション）とは、学習者が持つ科学的知見と相容れない信念や理解を指す。特に力や運動に関する「直観物理学」の研究において、人間は日常感覚に基づき、ニュートン力学以前の古代ギリシャのアリストテレス的力学に酷似した直観体系を持つことが明らかにされた。\n\n例えば「物体が動いている間は常に力が働き続けている」「重い物体ほど速く落下する」といった直観は、摩擦や空気抵抗のある日常体験から自然に形成される。これらの誤概念は学習者にとって極めて強固で整合的な体系をなしているため、形式的な講義だけでは容易に修正されない。\n\n授業指導では、生徒が抱く直観物理学的な誤認を肯定的に捉えた上で、予想と実験結果のずれを体験させることが欠かせない。グループでの議論や反証実験を通じて自らの前提を疑い、科学的証拠に基づいて思考を吟味する探究的な学習環境が求められる。",
