    body: "スイスの心理学者ジャン・ピアジェは、知性の発達を生体が環境に適応していく生物学的なプロセスとして捉えた。主著『知能の心理学』等において、認知構造（シェマ）が環境との相互作用を通じて発展する基本原理として同化、調節、均衡化の概念を提唱した。\n\n「同化」とは、新たな経験を既存のシェマに当てはめて解釈することである。既存のシェマでは処理できない不均衡な事態に直面すると、自らのシェマを環境に合わせて改変する「調節」が生じる。この同化と調節の矛盾を解消し、より高次の認知構造へと安定化させる動的な調和を「均衡化」と呼ぶ。\n\n教育実践においては、学習者がすでに持っている認知構造を尊重しつつ、適度な疑問や認知的葛藤を引き起こす教材提示が不可欠である。既知の知識と新しい課題との間に適度な認知的ギャップを設けることで、自発的な探究と主体的な概念再構築を促すことができる。",
