    body: "保存概念は、ピアジェの認知発達理論において前操作期から具体的操作期への質的転換を示す決定的な指標である。事物の形状や配置が変形しても、何かが加えられたり除かれたりしない限り、その数量的属性が保たれることを理解する思考の成立を指す。\n\n保存課題では、細長いコップに移し替えた液体の量や、間隔を広げた碁石の数などを判定させる。前操作期の子どもは最も目立つ知覚的特徴（水面の高さなど）に注意が集中（中心化）するが、具体的操作期に達すると、元に戻せるという「可逆性」や幅と高さの「相殺」を論理的に思考できるようになる。\n\n算数科や理科の初期教育では、児童が保存概念をどの程度獲得しているかを把握した指導が重要である。言葉による公式の教授に偏ることなく、具体物を実際に操作したり並べ替えたりする体験的活動を豊富に取り入れることで、論理的思考力の確実な定着を支える。",
