    body: "心理学者アルバート・バンデューラが確立した社会的認知理論において、特定の行動を成功裏に遂行できるという信念（自己効力感）は学習や行動変容の動機づけの中核をなす。バンデューラはこの信念を醸成する情報源として四つの明確な要因を特定した。\n\n第一に最も強力な影響を持つ「遂行行動の達成（成功体験）」、第二に他者の成功を観察する「代理的体験（モデリング）」、第三に他者からの励ましや説得である「言語的説得」、第四に心拍や緊張といった身体反応を解釈する「情動的・生理的状態」である。これらを認知的に統合して自信が形成される。\n\n学校教育や授業改善において、生徒の学習意欲を高める具体的な指導指針となる。小さな成功体験を積み重ねさせ、身近な仲間が課題を達成する姿を見せ、適切な称賛や励ましを与え、リラックスできる安全な教室環境を整えることで、生徒の自己効力感を大きく高めることができる。",
