    body: "アメリカの心理学者アーヴィング・ジャニスが1972年に提唱した集団思考（グループシンク）は、連帯感の強い組織や集団において、調和や満場一致を優先するあまり客観的な評価や異論が排除される欠陥的決定プロセスを指す。歴史的政策の失策を分析して体系化された。\n\n強い凝集性、外部からの孤立、独断的なリーダーシップ、危機的な情勢などが誘因となる。その結果、自集団への過大評価、倫理的優越の幻想、集団内での自己検閲、異論を唱える成員への同調圧力、満場一致の錯覚が生じ、代替案の徹底的な検討を著しく阻害する。\n\n生徒主体の学級活動や探究的なグループワークにおいて、特定の意見への盲従を防ぐ指導の指針となる。教師はあえて批判的な視点から意見を述べる役割（悪魔の代弁者）を置いたり、少数意見を安心して表明できる学級風土を育んだりする工夫が求められる。",
