    body: "集団極性化（グループ・ポラリゼーション）は、集団成員が討議を行うことで、成員全体の判断が当初の平均的傾向よりも極端な方向へシフトする現象である。リスクを好む方向へ傾くリスキー・シフトと、安全性を過度に重視するコーシャス・シフトの双方が含まれる。\n\nこの現象は情報的影響と規範的影響によって生じる。討議の中で自らの当初の意見を支持する新たな論拠に多く触れることで確信が強まり（情報的影響）、集団内で望ましいとされる極端な態度を示すことで他者から好意的に評価されようとする（規範的影響）ため、意見が先鋭化していく。\n\n学校での話し合い活動や生徒会活動において、集団討議が必ずしも中庸でバランスの取れた結論に至るわけではないことを念頭に置く必要がある。指導者は対立する多様な資料を提供し、多角的な視野から慎重に検討を深めさせるファシリテーションが重要である。",
