    body: "フランスの農業工学者マクシミリアン・リンゲルマンが綱引きの実験で見いだした現象に基づき、社会心理学者ラタネらが理論化した社会的手抜き（フリーライダー現象）は、集団作業において個人の動機づけが低下し努力が減退する現象である。\n\nリンゲルマンの実験では、綱を引く人数が増えるほど、一人あたりの発揮する力は減少することが示された。この原因は、個人の貢献度が集団全体の成果に埋没して評価されにくくなること（責任の分散）、および自分が手抜きをしても他者が補ってくれるだろうという期待などにある。\n\n協同学習や探究的なグループワークにおいて、特定の生徒だけが作業を負担する事態を避けるための必須知識である。教師は各成員に明確な役割を分担させ、個人の貢献を可視化して相互評価を導入するなど、全員が主体的に参画できる仕掛けを整えることが求められる。",
