    body: "他者が周囲に存在することが個人の作業遂行に与える影響について、古くはトリプレットの競走実験から研究されてきた。社会心理学者ロバート・ザイアンスは、他者の存在が作業効率を高める「社会的促進」と逆に低下させる「社会的抑制」を統一的に説明する動因説を提唱した。\n\nザイアンスは、他者の存在が個人の覚醒水準を高め、習熟した行動（優位反応）の表出を促すと論じた。そのため、単純な課題や十分に習熟した技能では正答が出やすくなり成果が向上するが、未習得の複雑な課題や思考を要する課題では誤反応が生じやすくなり、成果が阻害される。\n\n授業や学習環境の設計において極めて有益な示唆を与える。基礎的な計算練習や暗記の確認などは集団で競わせることで意欲が高まるが、新しい難解な概念の理解や深い思索を要する活動では、他者の視線による過度な緊張を避け、落ち着いて個別に取り組める配慮が効果的である。",
