    body: "アメリカの心理学者ソロモン・アッシュが1950年代に行った同調実験は、客観的な正解が明白である状況においてさえ、集団の圧力によって個人の判断が多数派の意見へと屈服する同調行動を実証した心理学史上の金字塔である。\n\n被験者は複数のサクラと同じ部屋に入り、標準線分と同じ長さの比較線分を選ぶ単純な視覚課題を与えられる。サクラ全員が意図的に明白な誤答を答えると、被験者の約3分の1が誤答に同調した。集団から排除される恐怖を避ける規範的影響や、自己の知覚を疑う情報的影響が働くことが判明した。\n\n学校空間におけるいじめの傍観や同調圧力の発生機序を解明する上で決定的な意義を持つ。集団内に一人でも異論を唱える味方がいれば同調率は激減することから、教師は教室において多様な意見や少数派の声を安心して表明できる心理的安全性を担保することが強く求められる。",
