    body: "アメリカの心理学者スタンレー・ミルグラムが1960年代に実施した服従実験（アイヒマン実験）は、権威者の指示のもとで普通の人間がどこまで残虐な行為に及ぶかを検証した。ナチスによるホロコーストの心理的背景を探る目的で企画された衝撃的な研究である。\n\n被験者は「学習における処罰の効果」を調べる実験と告げられ、生徒役の誤答に対して最高450ボルトまでの電気ショックを与える教師役を演じる。生徒役の悲鳴や抗議にもかかわらず、白衣を着た実験者の断固たる指示により、実に約65パーセントの被験者が致死レベルの最大電圧までボタンを押し続けた。\n\n主権者教育や人権教育において、盲目的な権威への服従を排し、自律的な批判的思考力を育成する重要性を示す重い証拠である。理不尽な命令や集団規範に対して自らの倫理観に基づいて疑い、「ノー」と言える主体的な市民性を学校教育の中で培う必要性を教えている。",
