    body: "1970年代初頭にアメリカの心理学者ジンバルドーらによって行われた実験であり、強い制度的環境や割り当てられた役割が個人の行動と性格をいかに変えてしまうかを検証するために計画された。心身ともに健康な学生を集めて看守役と囚人役に無作為に割り当て、模擬刑務所での生活を観察した。\n\n実験開始後まもなく、被験者たちは与えられた役割に急速に同化し、看守役は残虐な言動を示し、囚人役は強い服従と精神的疲弊に陥った。この結果は、個人の道徳性や人格特性よりも、制度的な立場や役割期待、匿名性といった状況的な要因が人間の振る舞いを決定づける強力な力を持つことを鮮明に示した。\n\n学校現場においても、生徒や教員が無意識のうちに固定的な役割に縛られ、権力関係やいじめの温床となる危険性を示唆している。学級集団における過度な規律や非対称な上下関係を警戒し、一人ひとりが主体的な判断力と人権感覚を保てる健全な集団風土づくりが不可欠である。",
