    body: "心理学者ラーナーによって提唱された概念であり、人々が抱く公平な世界観と認知の偏りに関する理論である。人間は世界の秩序や安定を信じたいという強い欲求を持つため、世の中では善人が報われ悪人が罰せられるという世界観を無意識に仮定する傾向がある。\n\nこの認知枠組みが働くと、理不尽な不運や犯罪に巻き込まれた被害者を目の当たりにした際、その世界観を守るために「被害者側にも落ち度があったのではないか」と原因を被害者の内面に帰属させてしまう。被害者非難の心理的防衛機制として働き、客観的な事実に基づかない偏見や差別を無自覚に正当化する認知の偏りを生み出す。\n\n学校におけるいじめ問題や生徒指導の場面において、「いじめられる側にも原因がある」という不当な責任転嫁が起きる心理的背景としても指摘される。教員は自他が陥りやすいこの認知の錯覚を自覚し、被害者の尊厳を守り公正かつ客観的に状況を判断する姿勢が重要である。",
