    body: "認知心理学者のコリンズとキリアンによって提唱された記憶構造のモデルであり、人間の意味記憶がどのように整理され保持されているかを説明した。人工知能の知識表現研究に着想を得て、概念が孤立した知識ではなく体系的な関係性の中で保持される仕組みを解明しようとした。\n\nこの理論では、概念はノード（節点）として表され、上位概念と下位概念が階層的なネットワークで結ばれている。属性情報は最もふさわしい階層に割り当てられて記憶の節約が図られ、ある概念が意識されると結合リンクを通じて関連する近隣の概念へと活性化が拡散する。この活性化の広がりにより、素早い連想や知識の検索、推論が可能となる。\n\n教育実践において、新しい知識を単語の丸暗記として教えるのではなく、概念図やマインドマップを用いて既習事項との有機的な結合を促す指導の有効性を裏づけている。概念間の階層性や関連性を意識させることで、生徒の深い理解と確実な記憶の定着が促される。",
