    body: "アメリカの心理学者マレーとモーガンによって開発された性格検査であり、精神分析の投映概念に基づき、無意識的な欲求や心理的力動を可視化するために生み出された。質問紙法では捉えにくい個人の潜在的な動機や対人関係の葛藤を多角的に把握する目的で広く用いられてきた。\n\n検査では、人物が登場する解釈の多様な場面が描かれた図版を提示し、そこに描かれている人物の感情や前後の出来事について物語を創作させる。被験者は物語の主人公に自己を投影し、達成欲求や親和欲求といった内面的な動機、あるいは抑圧された不満や葛藤を言語化する。解釈においては人物相互の関係性や結末の傾向が詳細に分析される。\n\n学校教育や教育相談の場面では、言葉でうまく自己の感情を表現できない児童生徒の内面理解や、登校しぶりなどの背景にある心理的要因の探索に役立てられる。ただし、高度な専門性と倫理的配慮が求められるため、他の検査と組み合わせた総合的な評価が不可欠である。",
