    body: "エビングハウスの連想研究や精神分析の知見を背景に発展した半構造化された投映法心理検査であり、簡便に実施できる人格査定の手法として確立された。完全に自由な刺激を用いる絵画検査と定型的な質問紙法の中間に位置し、回答者の言語表現を通じて内面を多角的に捉える。\n\n被験者は「私の将来は」「父は私に」といった短い刺激文の続きを直感的に書き加えて完全な文章を作る。未完成の文章を完成させる過程で、本人の自己評価、家族観、対人関係の葛藤、将来への展望などが意識的および無意識的に反映される。言語的な知能や表現力も同時に観察でき、受検者の全体的な心理状態を多面的に把握できる。\n\n教育現場においては、集団実施が比較的容易であることから、新学期の生徒理解や教育相談における初期アセスメントとして広く活用されている。教員が生徒の言葉の背後にある悩みや欲求を丁寧に読み解き、個別の教育支援や進路指導に生かすための重要な手がかりとなる。",
