    body: "スイスの心理学者コッホによって開発された投映法の描画検査であり、言語表現を必要としない非言語的な心理査定として世界中で普及した。樹木は古くから生命力の象徴とされ、自己の成長過程や内面的な人格構造を無意識のうちに映し出す媒体として注目された。\n\n被験者に1枚の白紙を渡し「実のなる木を1本描いてください」と教示する。描かれた樹木の幹、枝、根、葉、全体の配置や筆圧、実の有無などから、自己の安定性、外界への関心、情動の成熟度、過去の心理的傷つきなどを読み取る。言語を介さないため、言葉による防衛が働きにくく、自然な心理的状態が表出されやすい特徴を持つ。\n\n学校現場では、言語化が未熟な幼児や低学年児童、あるいは対人不安が強い生徒に対する心理的支援の導入として有効である。教員やカウンセラーが生徒の内面にある不安や葛藤を視覚的に捉え、無理のない受容的な関係性を構築するための対話の契機として活用される。",
