    body: "モレノのソシオメトリー理論から発展し、発達心理学者のコイエらによって精密化された集団内の対人関係測定手法である。学級や仲間集団における個々の成員の心理的地位を数量的に測定し、いじめや孤立といった集団適応の危機を早期に発見するために研究された。\n\n学級の仲間に対して「一緒に遊びたい人」「一緒に遊びたくない人」などを指名させ、好意的な指名数と否定的な指名数を集計する。その得点分布から、多くに好まれる「人気児」、否定指名が多い「拒絶児」、好悪どちらの指名も少ない「無視児」、賛否が分かれる「対立児」などに分類される。各ステータスは後の心理社会的適応や学業継続と密接に関係している。\n\n学校現場では、表面化しにくい人間関係の固定化や周縁化された生徒を客観的に把握するための貴重な資料となる。拒絶児に対する社会的スキルの指導や、学級全体で互いの良さを認め合う協働学習を仕組むなど、排除のない受容的な集団づくりに役立てられる。",
