    body: "教育心理学や社会心理学において重視されてきた概念であり、レヴィンの場の理論や集団力学研究を源流として発展した。物理的な教室環境だけでなく、学級内で交わされる相互作用や共有される規範、教師と生徒の間に形成される主観的な雰囲気が学習者の発達を左右すると捉える。\n\n学級風土は、親密性、摩擦、凝集性、秩序、教師の統率力や受容的態度など複数の次元から心理測定尺度を用いて測定される。競争的で批判的な風土では失敗への恐怖や不安が高まり学習意欲が減退する一方、互いを尊重し安心して発言できる風土では、協働的な問題解決や内発的な探究心が活発に喚起される。\n\n現代の学級経営において、学級風土の定期的な把握はいじめ防止や不登校の未然予防に不可欠とされている。教員は学級を単なる管理の対象ではなく、生徒全員が心理的安全性を感じられる共同体として醸成し、互いの差異を認め合える対話的な空間を設計することが求められる。",
