    body: "ローゼンタールらによって発見されたピグマリオン効果の対概念として名づけられた心理現象である。指導者や周囲の抱く期待が学習者の認知や行動に及ぼす影響を研究する中で、肯定的な期待のみならず、否定的な偏見や無関心がもたらす破壊的な作用が明らかとなった。\n\n教師や保護者が学習者に対して「この子は能力が低い」「どうせできない」といった否定的認知を抱くと、無意識のうちに指示が冷淡になったり挑戦の機会が減らされたりする。学習者はその消極的な態度を敏感に察知し、「自分は期待されていない」と内面化して自己効力感を失い、努力を放棄するため、結果として成績や能力の低下が現実化する。\n\n教育実践において教員が自身の抱く無意識の偏見や固定観念を自覚することの重大性を強く示唆している。指導者は生徒の過去のつまずきや外見、出自にとらわれず、すべての生徒が成長する可能性を信じ、粘り強い励ましと適切な足場かけを提供し続ける責任がある。",
