    body: "九州大学の三隅二不二によって体系化されたリーダーシップ理論であり、日本の集団力学研究の金字塔として世界的に知られている。西洋由来の理論をそのまま適用するのではなく、実際の組織行動の綿密な実証研究に基づいて構築された実践的で応用性の高いモデルである。\n\nリーダーの行動を、目標達成や計画遂行を促す「課題達成機能（P機能）」と、人間関係の調整やチームのチームワークを保つ「集団維持機能（M機能）」の2次元に整理した。両機能の強弱によって集団を4類型に分類し、PとMの双方が高いPM型の指導が、成員の職務満足度、生産性、組織への帰属意識のいずれにおいても最も優れた成果を上げることが実証された。\n\n学級経営や生徒指導において、教員が自身の指導行動を振り返るための優れた指標となっている。規律や学習課題の徹底だけを求めるのではなく、生徒同士の温かい人間関係や安心感を育てる配慮を両立させることで、充実した学級集団の発展が期待できる。",
