    body: "アメリカの心理学者フィードラーが唱えた組織心理学の理論であり、どんな状況でも有効な単一の理想的リーダーシップは存在しないとする前提から出発した。リーダー個人の性格特性と環境の相互作用を定量的に捉え、リーダーシップ研究に画期的な転換をもたらした。\n\nリーダーを人間関係志向型と課題志向型に分類し、状況の統制しやすさをリーダーと成員の関係、課題の明確さ、職位の権限の3要素で評価する。状況が極めて好意的な場合や逆に極めて不利な困難な状況では課題志向型が成果を上げ、中程度に好意的な状況では人間関係志向型が有効に機能することを実証的に示した。\n\n学校教育や特別活動における指導においても、固定的な指導スタイルに執着するのではなく、集団の発達段階や課題の難度に応じて指導方法を柔軟に適合させる重要性を示している。新学期の混乱期や行事前などの状況を見極め、適切な統率と受容を使い分ける力量が求められる。",
