    body: "バンデューラの社会的学習理論の中で論じられた重要なモデリング効果の一つであり、観察による行動変容のメカニズムを説明する概念である。新しい行動を獲得するだけでなく、他者の行動の結果を見ることで、個人の内部に存在する行動抑制が弱まる過程を解明した。\n\n個人が特定の禁止事項や社会規範を学習していても、モデルとなる他者がルールを逸脱し、しかも罰を受けず利益や賞賛を得ている姿を目撃すると、「自分も許されるのではないか」という認知が生じる。この代理的な結果の認知によって、それまで働いていた道徳的・社会的抑制が弱まり、禁止されていた不適切な行動を自発的に模倣して実行しやすくなる。\n\n学校現場における学級崩壊や授業中の私語、いじめの拡散を説明する上で重大な示唆を持つ。一人の生徒の規則違反を教員があいまいな態度で見過ごすと、周囲の生徒に脱抑制が連鎖して集団全体の規範が崩壊するため、公平で確固たるルール運用と善い行動への肯定的な注目が必要である。",
