    body: "社会心理学の父レヴィンが提唱した概念であり、人間が意思決定を行う際に生じる心理的緊張と葛藤の構造を幾何学的なトポロジー心理学の視点から定式化した。個人の内部で相反する動機が衝突し、行動の選択が阻害されるメカニズムを力学的に説明した。\n\nレヴィンは心理的な力を正と負の誘意性として捉え、葛藤を3つに類型化した。魅力的な2つの目標から1つを選ぶ「接近-接近葛藤」、望ましくない2つの選択肢の板挟みになる「回避-回避葛藤」、魅力と負担が同一の対象に共存する「接近-回避葛藤」である。特に回避-回避葛藤ではその場からの逃避が生じやすく、接近-回避葛藤では決断の停滞や不安が生じやすいとされる。\n\n生徒の進路選択や学習意欲の減退、生徒指導上の迷いを理解する上で極めて有効な枠組みである。教員は生徒が直面している葛藤の性質を正確に見極め、負の要因を緩和したり、新たな魅力的な選択肢を提示したりすることで、主体的な意思決定を支援することができる。",
