    body: "教育心理学者ジマーマンによって提唱された認知理論であり、自立した学習者がいかにして自身の学びを能動的に管理し改善していくかを体系化した。バンデューラの社会的認知理論を背景に持ち、学力や知能を固定的な能力ではなく自己制御可能な過程として捉えた。\n\n学習の進行を3つの相互に関連する段階からなる循環サイクルとして定式化した。目標設定や動機づけを行う「予見段階」、方策を実行しながら集中を保ち進捗を点検する「遂行段階」、学習結果を振り返り原因を分析して次への適応を図る「自己省察段階」である。この循環を経験することで、自己効力感が高まり、効果的な学習方略の選択が洗練されていく。\n\n主体的で深い学びを育む現代の学校教育において、指導設計の中核的枠組みとなっている。教員は単に知識を一方的に教えるのではなく、生徒自身が学習計画を立て、学習日誌や振り返りシートを活用して自己の学びを客観的に改善できるよう支援することが求められる。",
