    body: "社会心理学者バウマイスターらによって提唱された自己制御の容量モデルであり、人間の意志力や自己コントロールが筋肉のような有限の資源であるという仮説に基づく。現代の衝動制御や集中力の持続を巡る研究に絶大な影響を与え、活発な議論を巻き起こした。\n\n感情の抑制、選択の決断、誘惑への抵抗、思考の統制といったあらゆる自己制御の営みは、共通の限られた心的リソースを消費するとされる。そのため、ある課題で強い自制心を酷使するとリソースが消耗した「自我消耗」の状態に陥り、次に直面した無関係な課題において衝動的な行動を抑えられなくなったり、粘り強さが著しく低下したりする。\n\n学校生活における生徒の学習指導や生活指導に重要な警鐘を鳴らしている。授業中に過度な静粛や緊張を強いると、放課後の自習意欲が枯渇したりトラブルが増加したりするため、適切な休憩や肯定的な感情の回復を取り入れた無理のない指導設計が推奨される。",
