    body: "発達心理学や認知神経科学において提唱された実行機能の分化モデルであり、感情と認知の相互作用を解明するために発展した。マシュマロ実験などで測定される衝動制御のメカニズムを、脳科学的知見と発達段階の視点から詳細に整理した。\n\nクールな実行機能とは、抽象的な問題解決、作業記憶の保持と更新、認知的柔軟性など、情動的刺激の少ない冷静な状況で働く認知制御を指す。一方、ホットな実行機能とは、報酬や罰、強い感情や欲求が絡む場面において目先の誘惑を我慢し、将来の大きな利益のために衝動を遅延させる感情制御を指す。両者は前頭前野の異なる神経回路に依存し、発達の軌跡も異なる。\n\n学校教育において、高い知能や知識を持つ生徒であっても、対人関係の摩擦や感情的な葛藤の場面で適切に行動できない理由を説明している。知的な学習訓練だけでなく、社会性と情動の学習を取り入れ、感情の調整力を計画的に育てる包括的な指導が重要である。",
