    body: "発達心理学者セルマンによって提唱された社会的認知の発達段階理論であり、ピアジェの脱中心化の概念を対人関係や道徳性の理解へと応用した。子どもが他者の心をどのように理解し、対人関係の葛藤をどのように処理できるようになるかを追究した。\n\n視点取得の発達を0から4の5つの水準に分類した。自己と他者の視点を区別できない自己中心的段階から始まり、他者の視点の存在に気づく主観的段階、自己と他者の関係を双方向的に理解する自己内省的段階、関係を客観的に観察できる第三者視点、そして社会的・慣習的システムを踏まえた包括的な相互視点へと順次深化していく。\n\n道徳教育や生徒指導、いじめ防止の取り組みにおいて不可欠な理論的指針である。対人トラブルを抱える生徒に対し、一方的にとがめるだけでなく「相手はどう感じたと思うか」と他者視点を促す発問を重ねることで、共感性と協調的な問題解決能力を段階的に育てることができる。",
